export const SENTINEL_PRINTER_PY = "import sys\nimport os\nimport subprocess\nimport importlib\nimport json\n\n# \u2500\u2500\u2500 Directorio base \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\n\n# \u2500\u2500\u2500 Dependencias \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nREQUIRED_PACKAGES = {\n    \"flask\": \"Flask\",\n    \"flask_cors\": \"flask-cors\",\n    \"win32print\": \"pywin32\",\n    \"win32serviceutil\": \"pywin32\",\n    \"PIL\": \"Pillow\",\n}\n\ndef ensure_deps():\n    missing = []\n    for module, package in REQUIRED_PACKAGES.items():\n        try:\n            importlib.import_module(module)\n        except ImportError:\n            if package not in missing:\n                missing.append(package)\n    if missing:\n        print(f\"Instalando dependencias faltantes: {missing}\")\n        for pkg in missing:\n            try:\n                subprocess.check_call([sys.executable, \"-m\", \"pip\", \"install\", pkg])\n            except Exception as e:\n                print(f\"Error instalando {pkg}: {e}\")\n\nservice_commands = {\"install\", \"remove\", \"start\", \"stop\", \"restart\", \"debug\", \"update\"}\nrunning_as_service_cmd = len(sys.argv) > 1 and sys.argv[1].lower() in service_commands\nif not running_as_service_cmd or sys.argv[1].lower() == \"debug\":\n    ensure_deps()\n\n# \u2500\u2500\u2500 Importaciones Seguras \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nimport urllib.parse\nimport threading\nimport logging\nimport hashlib\nimport time\nimport sqlite3\nimport re\nfrom datetime import datetime\n\n# Fix DLL search path for pywin32 in elevated UAC environment\ntry:\n    pywin32_sys32 = os.path.join(sys.prefix, \"Lib\", \"site-packages\", \"pywin32_system32\")\n    win32_dir = os.path.join(sys.prefix, \"Lib\", \"site-packages\", \"win32\")\n    sys32_win = os.environ.get(\"SystemRoot\", r\"C:\\Windows\") + r\"\\System32\"\n    for d in (pywin32_sys32, win32_dir, sys32_win):\n        if os.path.exists(d) and hasattr(os, \"add_dll_directory\"):\n            try:\n                os.add_dll_directory(d)\n            except Exception:\n                pass\nexcept Exception:\n    pass\n\ntry:\n    import pywintypes\nexcept Exception:\n    pass\n\nimport win32print\nimport win32serviceutil\nimport win32service\nimport win32event\nimport servicemanager\nimport socket\n\n# PIL\ntry:\n    from PIL import Image, ImageWin\nexcept ImportError:\n    pass\n\nfrom flask import Flask, request, jsonify\nfrom flask_cors import CORS\n\n# \u2500\u2500\u2500 Configuraci\u00f3n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nPORT    = 3010\nVERSION = \"6.0.0\"\n\n# \u2500\u2500\u2500 Helpers Pro: Total en Letra & Detecci\u00f3n de Emojis \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef numero_a_letras(monto: float) -> str:\n    \"\"\"Convierte un monto num\u00e9rico en su representaci\u00f3n formal de texto en espa\u00f1ol (pesos mexicanos M.N.).\"\"\"\n    try:\n        monto = round(float(monto), 2)\n        entero = int(monto)\n        centavos = int(round((monto - entero) * 100))\n\n        UNIDADES = [\"\", \"UN\", \"DOS\", \"TRES\", \"CUATRO\", \"CINCO\", \"SEIS\", \"SIETE\", \"OCHO\", \"NUEVE\"]\n        DECENAS = [\"\", \"DIEZ\", \"VEINTE\", \"TREINTA\", \"CUARENTA\", \"CINCUENTA\", \"SESENTA\", \"SETENTA\", \"OCHENTA\", \"NOVENTA\"]\n        DIEZ_A_DIECINUEVE = [\"DIEZ\", \"ONCE\", \"DOCE\", \"TRECE\", \"CATORCE\", \"QUINCE\", \"DIECISEIS\", \"DIECISIETE\", \"DIECIOCHO\", \"DIECINUEVE\"]\n        CENTENAS = [\"\", \"CIENTO\", \"DOSCIENTOS\", \"TRESCIENTOS\", \"CUATROCIENTOS\", \"QUINIENTOS\", \"SEISCIENTOS\", \"SETECIENTOS\", \"OCHOCIENTOS\", \"NOVECIENTOS\"]\n\n        def _convertir_grupo(n):\n            if n == 0:\n                return \"\"\n            if n == 100:\n                return \"CIEN\"\n            c = n // 100\n            d = (n % 100) // 10\n            u = n % 10\n            texto = CENTENAS[c]\n            res_d = \"\"\n            if d == 1:\n                res_d = DIEZ_A_DIECINUEVE[u]\n            elif d == 2:\n                if u == 0: res_d = \"VEINTE\"\n                else: res_d = f\"VEINTI{UNIDADES[u]}\"\n            elif d > 2:\n                if u == 0: res_d = DECENAS[d]\n                else: res_d = f\"{DECENAS[d]} Y {UNIDADES[u]}\"\n            elif u > 0:\n                res_d = UNIDADES[u]\n\n            if texto and res_d:\n                return f\"{texto} {res_d}\"\n            return texto or res_d\n\n        if entero == 0:\n            texto_entero = \"CERO\"\n        else:\n            partes = []\n            millones = entero // 1_000_000\n            resto = entero % 1_000_000\n            miles = resto // 1_000\n            unidades = resto % 1_000\n\n            if millones > 0:\n                if millones == 1:\n                    partes.append(\"UN MILLON\")\n                else:\n                    partes.append(f\"{_convertir_grupo(millones)} MILLONES\")\n            if miles > 0:\n                if miles == 1:\n                    partes.append(\"UN MIL\")\n                else:\n                    partes.append(f\"{_convertir_grupo(miles)} MIL\")\n            if unidades > 0:\n                partes.append(_convertir_grupo(unidades))\n\n            texto_entero = \" \".join(partes)\n\n        moneda = \"PESO\" if entero == 1 else \"PESOS\"\n        return f\"SON: ({texto_entero} {moneda} {centavos:02d}/100 M.N.)\"\n    except Exception:\n        return \"\"\n\ndef has_emoji(text: str) -> bool:\n    \"\"\"Detecta si el texto contiene caracteres Emojis Unicode.\"\"\"\n    for char in text:\n        code = ord(char)\n        if (0x1F300 <= code <= 0x1F9FF) or (0x2600 <= code <= 0x27BF) or (0x1F600 <= code <= 0x1F64F) or (0x1F680 <= code <= 0x1F6FF):\n            return True\n    return False\n\n# MODO DE IMPRESI\u00d3N PREDETERMINADO: \"gdi\" o \"raw\"\n#   \"gdi\" \u2192 Renderizado gr\u00e1fico con fuentes de Windows (m\u00e1s elegante, profesional y compatible con cualquier tipo de impresora)\n#   \"raw\" \u2192 Env\u00edo de bytes ESC/POS crudos directamente a la impresora\nPRINT_MODE = \"gdi\"\n\n# \u2500\u2500\u2500 Configuraci\u00f3n de Impresoras y Tama\u00f1os de Papel \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nCONFIG_FILE = os.path.join(BASE_DIR, \"printer_config.json\")\n\ndef load_printer_config():\n    default_config = {\n        \"PRINTER_MAP\": {\n            \"cuentas\": \"CUENTAS\",\n            \"cocina\":  \"COCINA\",\n            \"barra\":   \"BARRA\",\n        },\n        \"PRINTER_PAPER_SIZES\": {\n            \"cuentas\": \"80mm\",\n            \"cocina\":  \"80mm\",\n            \"barra\":   \"80mm\",\n        },\n        \"LOGO_PATH\": \"C:\\\\buzon\\\\logo.jpg\",\n        \"FONT_NAME\": \"Segoe UI\",\n        \"FONT_SIZE_PT\": 11.0,\n        \"HEADER_FONT_SIZE_PT\": 16.0,\n        \"ITEM_FONT_SIZE_PT\": 11.0,\n        \"TOTAL_FONT_SIZE_PT\": 15.0,\n        \"MARGIN_LEFT_PX\": 10,\n        \"MARGIN_RIGHT_PX\": 25,\n        \"LINE_SPACING\": 4,\n        \"SHOW_DIVIDER\": True\n    }\n    if os.path.exists(CONFIG_FILE):\n        try:\n            with open(CONFIG_FILE, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n                if \"PRINTER_MAP\" in data and isinstance(data[\"PRINTER_MAP\"], dict):\n                    default_config[\"PRINTER_MAP\"].update(data[\"PRINTER_MAP\"])\n                if \"PRINTER_PAPER_SIZES\" in data and isinstance(data[\"PRINTER_PAPER_SIZES\"], dict):\n                    default_config[\"PRINTER_PAPER_SIZES\"].update(data[\"PRINTER_PAPER_SIZES\"])\n                if \"LOGO_PATH\" in data:\n                    default_config[\"LOGO_PATH\"] = data[\"LOGO_PATH\"]\n                if \"FONT_NAME\" in data:\n                    default_config[\"FONT_NAME\"] = data[\"FONT_NAME\"]\n                if \"FONT_SIZE_PT\" in data:\n                    default_config[\"FONT_SIZE_PT\"] = float(data[\"FONT_SIZE_PT\"])\n                if \"HEADER_FONT_SIZE_PT\" in data:\n                    default_config[\"HEADER_FONT_SIZE_PT\"] = float(data[\"HEADER_FONT_SIZE_PT\"])\n                if \"ITEM_FONT_SIZE_PT\" in data:\n                    default_config[\"ITEM_FONT_SIZE_PT\"] = float(data[\"ITEM_FONT_SIZE_PT\"])\n                if \"TOTAL_FONT_SIZE_PT\" in data:\n                    default_config[\"TOTAL_FONT_SIZE_PT\"] = float(data[\"TOTAL_FONT_SIZE_PT\"])\n                if \"MARGIN_LEFT_PX\" in data:\n                    default_config[\"MARGIN_LEFT_PX\"] = int(data[\"MARGIN_LEFT_PX\"])\n                if \"MARGIN_RIGHT_PX\" in data:\n                    default_config[\"MARGIN_RIGHT_PX\"] = int(data[\"MARGIN_RIGHT_PX\"])\n                if \"LINE_SPACING\" in data:\n                    default_config[\"LINE_SPACING\"] = int(data[\"LINE_SPACING\"])\n                if \"SHOW_DIVIDER\" in data:\n                    default_config[\"SHOW_DIVIDER\"] = bool(data[\"SHOW_DIVIDER\"])\n        except Exception as e:\n            print(f\"Error cargando config de impresoras: {e}\")\n    else:\n        try:\n            with open(CONFIG_FILE, \"w\", encoding=\"utf-8\") as f:\n                json.dump(default_config, f, indent=4, ensure_ascii=False)\n        except Exception:\n            pass\n    return default_config\n\nconfig_printers = load_printer_config()\nPRINTER_MAP = config_printers[\"PRINTER_MAP\"]\nPRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\nLOGO_PATH = config_printers[\"LOGO_PATH\"]\nFONT_NAME = config_printers[\"FONT_NAME\"]\nFONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n# \u2500\u2500\u2500 Flask app \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\napp = Flask(__name__)\nCORS(app)\napp.logger.disabled = True\nlog_flask = logging.getLogger(\"werkzeug\")\nlog_flask.setLevel(logging.ERROR)\n\ndef sanitize_text(text: str) -> str:\n    \"\"\"Remueve cualquier caracter de control binario residual de ESC/POS (como \\x1b, \\x1d, LE1, E1, etc.).\"\"\"\n    if not text:\n        return \"\"\n    # Remover secuencias residuales comunes de ESC/POS\n    text = re.sub(r'[\\x00-\\x1f\\x7f-\\x9f]', '', text)\n    text = re.sub(r'(?:LE[01]|E[01]|!\\d+)', '', text)\n    return text.strip()\n\nLOG_FILE = os.path.join(BASE_DIR, \"sentinel_printer.log\")\n\ndef get_logger():\n    logger = logging.getLogger(\"sentinel\")\n    if logger.handlers:\n        return logger\n    logger.setLevel(logging.INFO)\n    fmt = logging.Formatter(\"%(asctime)s [%(levelname)s] %(message)s\", \"%Y-%m-%d %H:%M:%S\")\n    fh = logging.FileHandler(LOG_FILE, encoding=\"utf-8\")\n    fh.setFormatter(fmt)\n    logger.addHandler(fh)\n    if sys.stdout and sys.stdout.isatty():\n        ch = logging.StreamHandler(sys.stdout)\n        ch.setFormatter(fmt)\n        logger.addHandler(ch)\n    return logger\n\nlog = get_logger()\n\n# \u2500\u2500\u2500 Parser de Comandos ESC/POS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef parse_escpos(raw_bytes: bytes) -> list:\n    \"\"\"\n    Decodifica un flujo de bytes ESC/POS y lo convierte en una lista de l\u00edneas estructuradas\n    con propiedades de alineaci\u00f3n, tama\u00f1o de fuente y negritas para su renderizado GDI.\n    \"\"\"\n    lines = []\n    current_line_text = \"\"\n    \n    align = 0  # 0=izq, 1=centro, 2=der\n    bold = False\n    size = 'normal'  # 'normal', 'big', 'small'\n\n    def flush_current():\n        nonlocal current_line_text\n        if current_line_text.strip():\n            lines.append({\n                'text': current_line_text.strip(),\n                'align': align,\n                'size': size,\n                'bold': bold\n            })\n            current_line_text = \"\"\n    \n    i = 0\n    n = len(raw_bytes)\n    \n    while i < n:\n        b = raw_bytes[i]\n        \n        # Comando ESC (0x1b / 27)\n        if b == 0x1b:\n            if i + 1 < n:\n                cmd = raw_bytes[i + 1]\n                # ESC @ (Inicializar impresora)\n                if cmd == 0x40:\n                    flush_current()\n                    align = 0\n                    bold = False\n                    size = 'normal'\n                    i += 2\n                    continue\n                # ESC a (Alineaci\u00f3n)\n                elif cmd == 0x61:\n                    if i + 2 < n:\n                        flush_current()\n                        align = raw_bytes[i + 2]\n                        i += 3\n                        continue\n                # ESC ! (Modo de impresi\u00f3n general)\n                elif cmd == 0x21:\n                    if i + 2 < n:\n                        mode = raw_bytes[i + 2]\n                        new_bold = bool(mode & 8)\n                        new_size = 'big' if (mode & 48) else 'normal'\n                        if new_bold != bold or new_size != size:\n                            flush_current()\n                            bold = new_bold\n                            size = new_size\n                        i += 3\n                        continue\n                # ESC E (Negrita)\n                elif cmd == 0x45:\n                    if i + 2 < n:\n                        new_bold = bool(raw_bytes[i + 2])\n                        if new_bold != bold:\n                            flush_current()\n                            bold = new_bold\n                        i += 3\n                        continue\n                # ESC d (Avanzar N l\u00edneas)\n                elif cmd == 0x64:\n                    if i + 2 < n:\n                        feed_count = raw_bytes[i + 2]\n                        flush_current()\n                        for _ in range(max(1, feed_count - 1)):\n                            lines.append({\n                                'text': '',\n                                'align': align,\n                                'size': size,\n                                'bold': bold\n                            })\n                        i += 3\n                        continue\n                # Descartar otros comandos ESC de 2 o 3 bytes\n                elif cmd in (0x4a, 0x33, 0x32, 0x4d, 0x7b, 0x56):\n                    i += 3\n                    continue\n            i += 2\n            continue\n            \n        # Comando GS (0x1d / 29)\n        elif b == 0x1d:\n            if i + 1 < n:\n                cmd = raw_bytes[i + 1]\n                # GS V (Corte de papel)\n                if cmd == 0x56:\n                    if i + 2 < n and raw_bytes[i + 2] in (65, 66):\n                        i += 4\n                        continue\n                    else:\n                        i += 3\n                        continue\n                elif cmd in (0x21, 0x42, 0x6b, 0x77, 0x68):\n                    i += 3\n                    continue\n            i += 2\n            continue\n            \n        # Salto de l\u00ednea (LF = 0x0a / 10)\n        elif b == 0x0a:\n            flush_current()\n            i += 1\n            \n        # Retorno de carro (CR = 0x0d / 13)\n        elif b == 0x0d:\n            if i + 1 < n and raw_bytes[i + 1] == 0x0a:\n                i += 1\n            else:\n                flush_current()\n                i += 1\n            \n        # Caracteres normales del ticket\n        else:\n            decoded = False\n            # Intentar decodificar secuencias UTF-8 multibyte (hasta 4 bytes) para preservar Emojis (\ud83c\udf2e, \ud83c\udf7a, \ud83d\udd14, \ud83d\udcb0, etc.)\n            for length in (4, 3, 2, 1):\n                if i + length <= n:\n                    try:\n                        char_str = raw_bytes[i:i+length].decode('utf-8')\n                        current_line_text += char_str\n                        i += length\n                        decoded = True\n                        break\n                    except UnicodeDecodeError:\n                        continue\n            if not decoded:\n                try:\n                    char_str = raw_bytes[i:i+1].decode('cp850')\n                except Exception:\n                    char_str = chr(b)\n                current_line_text += char_str\n                i += 1\n            \n    flush_current()\n        \n    # Sanitizar todas las l\u00edneas para remover basura binaria\n    cleaned_lines = []\n    for l in lines:\n        cleaned_text = sanitize_text(l['text'])\n        if cleaned_text or l['text'] == '':\n            cleaned_lines.append({**l, 'text': cleaned_text})\n\n    return cleaned_lines\n\n# \u2500\u2500\u2500 Motores de Impresi\u00f3n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef get_installed_printers() -> list:\n    flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS\n    return [p[2] for p in win32print.EnumPrinters(flags)]\n\ndef resolve_printer_name(key: str) -> str:\n    global PRINTER_MAP\n    try:\n        config_printers = load_printer_config()\n        PRINTER_MAP = config_printers.get(\"PRINTER_MAP\", PRINTER_MAP)\n    except Exception:\n        pass\n        \n    target = PRINTER_MAP.get(key.lower(), key)\n    installed = get_installed_printers()\n    if not installed:\n        raise ValueError(\"No hay impresoras instaladas en el sistema Windows.\")\n        \n    # 1. Coincidencia exacta\n    for p in installed:\n        if p.upper() == target.upper():\n            return p\n            \n    # 2. Coincidencia parcial (subcadena)\n    for p in installed:\n        if target.upper() in p.upper() or p.upper() in target.upper():\n            return p\n            \n    # 3. Fallback a la impresora predeterminada de Windows\n    try:\n        default_win = win32print.GetDefaultPrinter()\n        if default_win in installed:\n            log.info(f\"\u26a0\ufe0f Impresora '{target}' no mapeada expl\u00edcitamente. Redirigiendo a la predeterminada de Windows: '{default_win}'\")\n            return default_win\n    except Exception:\n        pass\n        \n    # 4. Fallback a la primera impresora instalada\n    first_printer = installed[0]\n    log.info(f\"\u26a0\ufe0f Impresora '{target}' no encontrada. Redirigiendo a la primera impresora disponible: '{first_printer}'\")\n    return first_printer\n\ndef send_raw_to_printer(printer_name: str, data_bytes: bytes):\n    hPrinter = win32print.OpenPrinter(printer_name)\n    try:\n        job_name = f\"COCINET-RAW-{datetime.now().strftime('%H%M%S')}\"\n        win32print.StartDocPrinter(hPrinter, 1, (job_name, None, \"RAW\"))\n        try:\n            win32print.StartPagePrinter(hPrinter)\n            win32print.WritePrinter(hPrinter, data_bytes)\n            win32print.EndPagePrinter(hPrinter)\n        finally:\n            win32print.EndDocPrinter(hPrinter)\n    finally:\n        win32print.ClosePrinter(hPrinter)\n\ndef draw_logo_on_dc(hDC, logo_path: str, printable_width: int, y_start: int, dpi_y: int) -> int:\n    \"\"\"Carga y dibuja el logotipo centrado en el DC del ticket, retornando la nueva coordenada Y.\"\"\"\n    target_logo = None\n    possible_paths = [\n        logo_path,\n        \"C:\\\\buzon\\\\logoroy.png\",\n        \"C:\\\\buzon\\\\logo.png\",\n        \"C:\\\\buzon\\\\logo.jpg\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logoroy.png\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logo.png\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logo.jpg\",\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logoroy.png\"),\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logo.png\"),\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logo.jpg\"),\n    ]\n    for p in possible_paths:\n        if p and os.path.exists(p):\n            target_logo = p\n            break\n\n    if not target_logo:\n        log.warning(\"No se encontr\u00f3 logotipo f\u00edsico en ninguna de las rutas de b\u00fasqueda.\")\n        return y_start\n\n    try:\n        from PIL import Image, ImageWin\n        img = Image.open(target_logo)\n        if img.mode != \"RGB\":\n            img = img.convert(\"RGB\")\n            \n        w, h = img.size\n        max_logo_width = int(printable_width * 0.45)\n        scale = max_logo_width / float(w)\n        new_w = max_logo_width\n        new_h = int(h * scale)\n        \n        img = img.resize((new_w, new_h), Image.Resampling.LANCZOS)\n        margin_left = 25\n        x_start = margin_left + max(0, (printable_width - new_w) // 2)\n        \n        hdc_handle = hDC.GetSafeHdc()\n        dib = ImageWin.Dib(img)\n        dib.draw(hdc_handle, (x_start, y_start, x_start + new_w, y_start + new_h))\n        return y_start + new_h + 15\n    except Exception as e:\n        log.error(f\"Error renderizando el logotipo GDI ({target_logo}): {e}\")\n        return y_start\n\ndef wrap_and_draw_text(hDC, text: str, margin_left: int, margin_right: int, printable_width: int, y: int, align: int = 0, line_spacing: int = 4) -> int:\n    \"\"\"Renderiza texto con ajuste de l\u00ednea autom\u00e1tico para evitar recortes en los bordes del papel.\"\"\"\n    if not text:\n        return y\n        \n    text_w, text_h = hDC.GetTextExtent(text)\n    if text_w <= printable_width:\n        if align == 1:    # Centro\n            x = margin_left + (printable_width - text_w) // 2\n        elif align == 2:  # Derecha\n            x = margin_left + printable_width - text_w\n        else:             # Izquierda\n            x = margin_left\n        hDC.TextOut(x, y, text)\n        return y + text_h + line_spacing\n\n    words = text.split(\" \")\n    lines_to_draw = []\n    curr_line = \"\"\n    \n    for word in words:\n        test_line = f\"{curr_line} {word}\".strip() if curr_line else word\n        w, _ = hDC.GetTextExtent(test_line)\n        if w <= printable_width:\n            curr_line = test_line\n        else:\n            if curr_line:\n                lines_to_draw.append(curr_line)\n            w_word, _ = hDC.GetTextExtent(word)\n            if w_word > printable_width:\n                sub = \"\"\n                for char in word:\n                    if hDC.GetTextExtent(sub + char)[0] <= printable_width:\n                        sub += char\n                    else:\n                        lines_to_draw.append(sub)\n                        sub = char\n                curr_line = sub\n            else:\n                curr_line = word\n                \n    if curr_line:\n        lines_to_draw.append(curr_line)\n        \n    for l_text in lines_to_draw:\n        tw, th = hDC.GetTextExtent(l_text)\n        if align == 1:    # Centro\n            x = margin_left + (printable_width - tw) // 2\n        elif align == 2:  # Derecha\n            x = margin_left + printable_width - tw\n        else:             # Izquierda\n            x = margin_left\n        hDC.TextOut(x, y, l_text)\n        y += th + line_spacing\n        \n    return y\n\ndef send_gdi_to_printer(printer_name: str, data_bytes: bytes, ticket_type: str = \"comanda\"):\n    \"\"\"Parsea el ticket de comandos ESC/POS y lo dibuja vectorialmente usando el GDI de Windows.\"\"\"\n    import pywintypes\n    import win32ui\n    import win32con\n\n    global PRINTER_MAP, PRINTER_PAPER_SIZES, LOGO_PATH, FONT_NAME, FONT_SIZE_PT\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n    PRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\n    LOGO_PATH = config_printers[\"LOGO_PATH\"]\n    FONT_NAME = config_printers[\"FONT_NAME\"]\n    FONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n    parsed_lines = parse_escpos(data_bytes)\n    \n    printer_key = \"cuentas\"\n    for k, v in PRINTER_MAP.items():\n        if v.upper() == printer_name.upper():\n            printer_key = k\n            break\n            \n    paper_size = PRINTER_PAPER_SIZES.get(printer_key, \"80mm\")\n    \n    hDC = win32ui.CreateDC()\n    hDC.CreatePrinterDC(printer_name)\n    hDC.SetMapMode(win32con.MM_TEXT)\n    hDC.SetBkMode(win32con.TRANSPARENT)\n    \n    dpi_y = hDC.GetDeviceCaps(win32con.LOGPIXELSY) or 203\n    \n    # Obtener el ancho real de la superficie de impresi\u00f3n informada por el driver de Windows (DC)\n    dev_width = hDC.GetDeviceCaps(win32con.HORZRES) or hDC.GetDeviceCaps(win32con.PHYSICALWIDTH)\n    if dev_width and dev_width > 150:\n        width = dev_width\n    else:\n        width = 370 if paper_size == \"58mm\" else 540\n        \n    margin_left = 15 if paper_size == \"58mm\" else 25\n    margin_right = 15 if paper_size == \"58mm\" else 25\n    printable_width = width - margin_left - margin_right\n    job_name = f\"COCINET-GDI-{paper_size}-{datetime.now().strftime('%H%M%S')}\"\n    hDC.StartDoc(job_name)\n    hDC.StartPage()\n    \n    font_cache = {}\n    \n    def get_font(name, pt_size, is_bold, is_italic=False, use_emoji_font=False):\n        font_name_to_use = \"Segoe UI Emoji\" if (use_emoji_font or name == \"Segoe UI Emoji\") else name\n        key = (font_name_to_use, pt_size, is_bold, is_italic)\n        if key in font_cache:\n            return font_cache[key]\n        height = int(pt_size * dpi_y / 72)\n        f = win32ui.CreateFont({\n            \"name\": font_name_to_use,\n            \"height\": height,\n            \"weight\": win32con.FW_BOLD if is_bold else win32con.FW_NORMAL,\n            \"italic\": is_italic,\n            \"charset\": win32con.DEFAULT_CHARSET\n        })\n        font_cache[key] = f\n        return f\n\n    y = 20\n    \n    # Dibujar logotipo para todos los tickets comerciales (cuentas/precuentas/caja)\n    if ticket_type.lower() not in [\"cocina\", \"barra\"]:\n        y = draw_logo_on_dc(hDC, LOGO_PATH, width, y, dpi_y)\n    \n    # Escalar tama\u00f1o base de tipograf\u00eda\n    base_pt = FONT_SIZE_PT\n    if paper_size == \"58mm\":\n        base_pt = base_pt * 0.82\n        \n    # Pre-procesamiento: separar renglones concatenados (ej: m\u00faltiples productos pegados o SUBTOTAL y TOTAL)\n    expanded_lines = []\n    for l in parsed_lines:\n        txt = l['text'].strip()\n        if not txt:\n            expanded_lines.append(l)\n            continue\n            \n        # 1. Separar si vienen m\u00faltiples productos concatenados en una sola l\u00ednea (ej: \"6x TACO DE PASTOR (MA\u00cdZ) $132.002x REFRESCOS $76.00\")\n        item_split_pattern = r'(\\d+\\s*(?:x|X)\\s+.*?(?:\\$?[0-9]+(?:\\.[0-9]{1,2})?)(?=\\s*\\d+\\s*(?:x|X)\\s+|$))'\n        found_items = re.findall(item_split_pattern, txt, flags=re.IGNORECASE)\n        if len(found_items) > 1:\n            for item_str in found_items:\n                if item_str.strip():\n                    expanded_lines.append({**l, 'text': item_str.strip()})\n            continue\n\n        # 2. Evitar recortar 'SUBTOTAL' en 'SUB' + 'TOTAL' usando Lookbehind Negativo (?<!SUB)\n        keywords_pattern = r'(?=(?:RFC|SUC|FOLIO|REIMPRESION|PRECUENTA|MESA|FECHA|HORA|PAGO|SUBTOTAL|(?<!SUB)TOTAL|PROPINA|DESCUENTO|CAMBIO)\\s*:)'\n        found_parts = re.split(keywords_pattern, txt, flags=re.IGNORECASE)\n        if len(found_parts) > 1:\n            for p in found_parts:\n                if p.strip():\n                    expanded_lines.append({**l, 'text': p.strip()})\n        else:\n            expanded_lines.append(l)\n\n    header_drawn = False\n    in_table_phase = False\n    header_metadata_passed = False\n        \n    for line in expanded_lines:\n        text = line['text'].strip()\n        alignment = line['align']\n        size_mode = line['size']\n        is_bold = line['bold']\n        line_has_emoji = has_emoji(text)\n        \n        # 1. L\u00edneas divisorias vectoriales elegantes\n        if len(text) >= 10 and all(c in ('-', '=', '_', '*') for c in text):\n            pen = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x94a3b8)\n            hDC.SelectObject(pen)\n            hDC.MoveTo(margin_left, y + 5)\n            hDC.LineTo(width - margin_right, y + 5)\n            y += 14\n            continue\n            \n        # 2. Renglon vac\u00edo\n        if not text:\n            f = get_font(FONT_NAME, base_pt, False)\n            hDC.SelectObject(f)\n            _, text_height = hDC.GetTextExtent(\" \")\n            y += text_height\n            continue\n            \n        # Determinar el tama\u00f1o de tipograf\u00eda (pt)\n        if size_mode == 'big':\n            pt = base_pt * 1.30\n            bold_to_use = True\n        elif size_mode == 'small':\n            pt = base_pt * 0.75\n            bold_to_use = is_bold\n        else:\n            pt = base_pt\n            bold_to_use = is_bold\n            \n        f = get_font(FONT_NAME, pt, bold_to_use, use_emoji_font=line_has_emoji)\n        hDC.SelectObject(f)\n\n        # 3. Detectar Rengl\u00f3n de Producto (requiere prefijo de cantidad \"1x\", \"6x\" o importe final \"$XX.XX\")\n        EXCLUDED_KEYS = [\"MESA\", \"HORA\", \"FOLIO\", \"FECHA\", \"COMANDA\", \"SUBTOTAL\", \"TOTAL\", \"PROPINA\", \"DESCUENTO\", \"DIR:\", \"TEL:\", \"EMAIL:\", \"CLIENTE:\", \"ATENDIO\", \"MESERO\", \"REIMPRESION\", \"CUENTA\", \"PRECUENTA\", \"SUC:\", \"RFC:\", \"REGIMEN\", \"R\u00c9GIMEN\", \"LUGAR\", \"EXPEDICION\", \"EXPEDICI\u00d3N\", \"FORMA DE PAGO\", \"PAGA CON\", \"RECIBIDO\", \"CAMBIO\", \"DATOS DE ENVIO\", \"SON:\", \"PAGADO\", \"EFECTIVO\", \"TARJETA\", \"TRANSFERENCIA\", \"DESTINO:\", \"GRACIAS\", \"VISITA\", \"VUELVA\", \"OBS:\"]\n        \n        has_qty = bool(re.match(r'^\\s*\\d+\\s*(?:x|X)?\\s+', text, re.IGNORECASE))\n        has_price = bool(re.search(r'\\$?([0-9]+(?:[\\.,][0-9]{1,2})?)\\s*$', text))\n        \n        # El rengl\u00f3n de producto se identifica de forma absoluta por tener cantidad inicial o importe final sin ser clave de cabecera\n        is_item_line = bool(\n            (has_qty or has_price) and\n            not any(text.upper().startswith(k) for k in EXCLUDED_KEYS) and\n            not any(c in ('-', '=', '_', '*') for c in text)\n        )\n\n        log.info(f\"  [GDI v5.0.0]: '{text}' | item={is_item_line}\")\n\n        # Dibujar encabezado de tabla estilizada justo despu\u00e9s de los metadatos y antes del primer producto\n        if is_item_line and not header_drawn and ticket_type.lower() in [\"cuentas\", \"cuenta\", \"precuenta\"]:\n            header_drawn = True\n            in_table_phase = True\n            \n            # Espaciado vectorial para bajar la tabla y dejarla clara debajo de MESA/FECHA\n            y += 6\n            \n            # L\u00ednea superior del encabezado de tabla\n            pen_tbl = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x334155)\n            hDC.SelectObject(pen_tbl)\n            hDC.MoveTo(margin_left, y + 2)\n            hDC.LineTo(width - margin_right, y + 2)\n            y += 8\n            \n            # Encabezado de 1 rengl\u00f3n: CANT / DESCRIPCI\u00d3N                IMPORTE\n            fh = get_font(FONT_NAME, base_pt * 0.88, True)\n            hDC.SelectObject(fh)\n            hDC.TextOut(margin_left, y, \"CANT / DESCRIPCI\u00d3N\")\n            w_imp, h_imp = hDC.GetTextExtent(\"IMPORTE\")\n            x_imp = max(margin_left + 150, width - margin_right - w_imp)\n            hDC.TextOut(x_imp, y, \"IMPORTE\")\n            y += h_imp + 4\n            \n            # L\u00ednea inferior del encabezado\n            hDC.MoveTo(margin_left, y + 2)\n            hDC.LineTo(width - margin_right, y + 2)\n            y += 10\n\n        # Renderizar Rengl\u00f3n de Producto (1 solo rengl\u00f3n estricto por producto, truncando la descripci\u00f3n si es muy larga)\n        if is_item_line:\n            desc = text.strip()\n            price_str = None\n            qty_str = None\n            \n            # 1. Extraer precio al final de la l\u00ednea si existe\n            p_m = re.search(r'\\$?([0-9]+(?:\\.[0-9]{1,2})?)\\s*$', desc)\n            if p_m:\n                price_str = p_m.group(1)\n                desc = desc[:p_m.start()].strip()\n                \n            # 2. Extraer cantidad al inicio si existe\n            q_m = re.match(r'^\\s*(\\d+)\\s*(?:x|X)?\\s+(.*)$', desc, re.IGNORECASE)\n            if q_m:\n                qty_str = q_m.group(1)\n                desc = q_m.group(2).strip()\n                \n            qty_val = int(qty_str) if (qty_str and qty_str.isdigit()) else 1\n            price_num = float(price_str.replace(',', '')) if price_str else 0.0\n            \n            # 3. Dibujar el IMPORTE alineado a la derecha en la misma l\u00ednea\n            imp_str = f\"${price_num:.2f}\" if price_num > 0 else \"\"\n            fp = get_font(FONT_NAME, pt * 0.95, True)\n            hDC.SelectObject(fp)\n            \n            if imp_str:\n                pr_w, pr_h = hDC.GetTextExtent(imp_str)\n                x_right = max(margin_left + 120, width - margin_right - pr_w)\n                hDC.TextOut(x_right, y, imp_str)\n            else:\n                pr_w, pr_h = 0, int(pt * dpi_y / 72)\n                x_right = width - margin_right\n                \n            # 4. Formatear la descripci\u00f3n limpia con su cantidad (ej: \"1x TACO DE PASTOR (MA\u00cdZ)\")\n            full_desc_left = f\"{qty_val}x {desc}\"\n                \n            # 5. Truncar la descripci\u00f3n si excede el espacio disponible antes del importe\n            fd = get_font(FONT_NAME, pt * 0.95, True, use_emoji_font=has_emoji(full_desc_left))\n            hDC.SelectObject(fd)\n            \n            max_desc_w = x_right - margin_left - 10\n            curr_desc = full_desc_left\n            \n            if max_desc_w > 40:\n                while curr_desc and hDC.GetTextExtent(curr_desc)[0] > max_desc_w:\n                    curr_desc = curr_desc[:-1]\n                if len(curr_desc) < len(full_desc_left):\n                    curr_desc = curr_desc.rstrip() + \"...\"\n            \n            hDC.TextOut(margin_left, y, curr_desc)\n            _, desc_h = hDC.GetTextExtent(curr_desc)\n            \n            y += max(desc_h, pr_h, int(pt * dpi_y / 72)) + 5\n            continue\n        \n        # 3.5. Formatear y renderizar Fecha y Hora con Emojis \ud83d\udcc5 y \u23f0 (Negrita, oscuro y legible)\n        if text.upper().startswith(\"FECHA:\") or text.upper().startswith(\"HORA:\") or \"FECHA:\" in text.upper():\n            clean_date_text = text\n            if \"FECHA:\" in clean_date_text.upper():\n                date_val = re.sub(r'^FECHA:\\s*', '', clean_date_text, flags=re.IGNORECASE).strip()\n                if ',' in date_val:\n                    parts = date_val.split(',', 1)\n                    f_part = parts[0].strip()\n                    h_part = parts[1].strip()\n                    formatted_dt = f\"\ud83d\udcc5 {f_part}   \u23f0 {h_part}\"\n                else:\n                    formatted_dt = f\"\ud83d\udcc5 {date_val}\"\n            elif clean_date_text.upper().startswith(\"HORA:\"):\n                hora_val = clean_date_text[5:].strip()\n                formatted_dt = f\"\u23f0 {hora_val}\"\n            else:\n                formatted_dt = text\n\n            f_dt = get_font(FONT_NAME, pt * 1.05, True, use_emoji_font=True)\n            hDC.SelectObject(f_dt)\n            y = wrap_and_draw_text(hDC, formatted_dt, margin_left, margin_right, printable_width, y, align=0, line_spacing=4)\n            continue\n        \n        # 4. Formatear y alinear Totales, Subtotales, Cambios, etc.\n        total_match = re.search(r'^(TOTAL A PAGAR|TOTAL|SUBTOTAL|SUMA TOTAL|PROPINA MESEROS|PROPINA VOLUNTARIA|PROPINA|DESCUENTO|FORMA DE PAGO|PAGO|PAGA CON|RECIBIDO|CAMBIO|ATENDIDO POR|MESERO|MESA)\\s*:?\\s*(.*)$', text, re.IGNORECASE)\n        has_total_keyword = bool(total_match or (\"TOTAL\" in text.upper() and \"SUBTOTAL\" not in text.upper()))\n        \n        if has_total_keyword:\n            if in_table_phase:\n                in_table_phase = False\n                pen_end = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x334155)\n                hDC.SelectObject(pen_end)\n                hDC.MoveTo(margin_left, y + 2)\n                hDC.LineTo(width - margin_right, y + 2)\n                y += 12\n\n            if total_match:\n                label = total_match.group(1).upper() + \":\"\n                val = total_match.group(2).strip()\n            else:\n                parts = text.split(\":\", 1)\n                label = parts[0].strip().upper() + \":\"\n                val = parts[1].strip() if len(parts) > 1 else \"\"\n\n            is_total_label = (\"TOTAL\" in label or \"TOTAL\" in text.upper()) and \"SUBTOTAL\" not in text.upper()\n            \n            lbl_pt = pt * 1.15 if is_total_label else pt\n            lbl_str = \"TOTAL A PAGAR:\" if is_total_label else label\n            fl = get_font(FONT_NAME, lbl_pt, is_total_label or is_bold, use_emoji_font=has_emoji(lbl_str))\n            hDC.SelectObject(fl)\n            \n            # Posicionar etiquetas al margen izquierdo para evitar colisi\u00f3n con importes a la derecha\n            lbl_w, lbl_h = hDC.GetTextExtent(lbl_str)\n            x_lbl = margin_left\n            hDC.TextOut(x_lbl, y, lbl_str)\n            \n            val_pt = pt * 1.25 if is_total_label else pt\n            fb = get_font(FONT_NAME, val_pt, True, use_emoji_font=has_emoji(val))\n            hDC.SelectObject(fb)\n            val_width, val_height = hDC.GetTextExtent(val)\n            x_val = max(margin_left + lbl_w + 10, width - margin_right - val_width)\n            hDC.TextOut(x_val, y, val)\n            y += max(lbl_h, val_height) + 6\n            \n            # SI ES EL TOTAL PRINCIPAL, DIBUJAR AUTOM\u00c1TICAMENTE EL TOTAL EN LETRA DEBAJO\n            if is_total_label:\n                monto_match = re.search(r'([0-9.,]+)', val)\n                if monto_match:\n                    try:\n                        monto_clean = float(monto_match.group(1).replace(',', ''))\n                        letra_str = numero_a_letras(monto_clean)\n                        if letra_str:\n                            f_letra = get_font(FONT_NAME, base_pt * 0.82, True, is_italic=True, use_emoji_font=has_emoji(letra_str))\n                            hDC.SelectObject(f_letra)\n                            y = wrap_and_draw_text(hDC, letra_str, margin_left, margin_right, printable_width, y, align=1, line_spacing=3)\n                            \n                            pen_tot = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x475569)\n                            hDC.SelectObject(pen_tot)\n                            hDC.MoveTo(margin_left, y + 2)\n                            hDC.LineTo(width - margin_right, y + 2)\n                            y += 12\n                    except Exception as e:\n                        log.error(f\"Error calculando total en letra: {e}\")\n            continue\n\n        # 5. Renderizar notas del producto (l\u00edneas con asterisco *) con it\u00e1licas e indentadas\n        if text.startswith('*') or text.startswith('>'):\n            f_italic = get_font(FONT_NAME, pt, False, is_italic=True, use_emoji_font=has_emoji(text))\n            hDC.SelectObject(f_italic)\n            y = wrap_and_draw_text(hDC, text, margin_left + 40, margin_right, printable_width - 40, y, align=0, line_spacing=3)\n            continue\n            \n        # 6. Renderizar l\u00edneas comunes y pie de p\u00e1gina con envoltorio autom\u00e1tico\n        f_line = get_font(FONT_NAME, pt, bold_to_use, use_emoji_font=line_has_emoji)\n        hDC.SelectObject(f_line)\n        y = wrap_and_draw_text(hDC, text, margin_left, margin_right, printable_width, y, align=alignment, line_spacing=4)\n        \n    hDC.EndPage()\n    hDC.EndDoc()\n    hDC.DeleteDC()\n\ndef print_data(printer_name: str, data_bytes: bytes, ticket_type: str = \"comanda\"):\n    \"\"\"Bypass unificado para imprimir en RAW o renderizar vectorialmente en GDI.\"\"\"\n    if PRINT_MODE.lower() == \"gdi\":\n        try:\n            log.info(f\"Imprimiendo v\u00eda GDI vectorial ({ticket_type}) en: '{printer_name}'\")\n            send_gdi_to_printer(printer_name, data_bytes, ticket_type)\n        except Exception as e:\n            log.error(f\"Fallo en GDI: {e}. Reintentando con bypass RAW...\")\n            send_raw_to_printer(printer_name, data_bytes)\n    else:\n        send_raw_to_printer(printer_name, data_bytes)\n\n# \u2500\u2500\u2500 Endpoints de Flask \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n@app.route(\"/config\", methods=[\"GET\", \"POST\"])\ndef manage_config():\n    if request.method == \"POST\":\n        try:\n            data = request.get_json(silent=True) or {}\n            current = load_printer_config()\n            current.update(data)\n            with open(CONFIG_FILE, \"w\", encoding=\"utf-8\") as f:\n                json.dump(current, f, indent=4, ensure_ascii=False)\n            load_printer_config()\n            return jsonify({\"success\": True, \"config\": current})\n        except Exception as e:\n            return jsonify({\"success\": False, \"error\": str(e)}), 500\n    else:\n        cfg = load_printer_config()\n        return jsonify({\"success\": True, \"config\": cfg})\n\n@app.route(\"/download/<filename>\", methods=[\"GET\"])\ndef download_sentinel_file(filename):\n    safe_files = [\"sentinel_printer.py\", \"instalador.bat\", \"instalador_sentinela.py\", \"printer_config.json\"]\n    if filename not in safe_files:\n        return jsonify({\"error\": \"File not allowed\"}), 400\n    file_path = os.path.join(BASE_DIR, filename)\n    if not os.path.exists(file_path):\n        return jsonify({\"error\": \"File not found\"}), 404\n    from flask import send_file\n    return send_file(file_path, as_attachment=True)\n\n@app.route(\"/status\", methods=[\"GET\"])\ndef get_status():\n    global PRINTER_MAP, PRINTER_PAPER_SIZES, LOGO_PATH, FONT_NAME, FONT_SIZE_PT\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n    PRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\n    LOGO_PATH = config_printers[\"LOGO_PATH\"]\n    FONT_NAME = config_printers[\"FONT_NAME\"]\n    FONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n    installed = get_installed_printers()\n    mapped = {\n        key: {\n            \"windows_name\": win_name,\n            \"paper_size\": PRINTER_PAPER_SIZES.get(key, \"80mm\"),\n            \"available\": any(p.upper() == win_name.upper() for p in installed),\n        }\n        for key, win_name in PRINTER_MAP.items()\n    }\n    return jsonify({\n        \"status\": \"online\",\n        \"service\": \"COCINET Print Sentinel\",\n        \"version\": VERSION,\n        \"port\": PORT,\n        \"print_mode\": PRINT_MODE,\n        \"config\": config_printers,\n        \"installed_printers\": installed,\n        \"mapped_printers\": mapped,\n    })\n\n@app.route(\"/printers\", methods=[\"GET\"])\ndef list_printers():\n    global PRINTER_MAP\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n\n    installed = get_installed_printers()\n    default = win32print.GetDefaultPrinter()\n    return jsonify({\"printers\": installed, \"default\": default, \"mapped\": PRINTER_MAP})\n\n@app.route(\"/print\", methods=[\"POST\"])\ndef print_ticket():\n    data = request.get_json(silent=True)\n    if not data:\n        return jsonify({\"success\": False, \"error\": \"No data received\"}), 400\n        \n    printer_key  = data.get(\"printer\", \"cuentas\")\n    raw_data_url = data.get(\"raw_data\", \"\")\n    raw_bytes    = urllib.parse.unquote_to_bytes(raw_data_url)\n    \n    if check_duplicate_and_register(raw_bytes):\n        log.info(f\"\u26a0\ufe0f Ticket duplicado detectado v\u00eda API POST /print. Omitiendo impresi\u00f3n f\u00edsica.\")\n        return jsonify({\"success\": True, \"ignored\": True, \"reason\": \"duplicate\", \"bytes_sent\": 0})\n        \n    try:\n        printer_name = resolve_printer_name(printer_key)\n        print_data(printer_name, raw_bytes, ticket_type=printer_key)\n        return jsonify({\"success\": True, \"printer_used\": printer_name, \"bytes_sent\": len(raw_bytes)})\n    except Exception as e:\n        log.error(f\"\u274c Error en API /print: {e}\")\n        return jsonify({\"success\": False, \"error\": str(e)}), 500\n\n@app.route(\"/test-print\", methods=[\"POST\"])\ndef test_print():\n    try:\n        data         = request.get_json(silent=True) or {}\n        printer_key  = data.get(\"printer\", \"cuentas\")\n        printer_name = resolve_printer_name(printer_key)\n\n        ESC = b\"\\x1b\"\n        GS  = b\"\\x1d\"\n        now = datetime.now().strftime(\"%d/%m/%Y %H:%M:%S\")\n\n        test_bytes = (\n            ESC + b\"@\"\n            + ESC + b\"a\\x01\"\n            + ESC + b\"!\\x18\"\n            + \"\ud83c\udf2e TACOS ROY AZUCENAS \ud83c\udf2e\\n\".encode(\"utf-8\")\n            + ESC + b\"!\\x00\"\n            + \"=== TICKET PRO GDI VECTORIAL ===\\n\\n\".encode(\"utf-8\")\n            + ESC + b\"a\\x00\"\n            + f\"Impresora : {printer_name}\\n\".encode(\"utf-8\")\n            + f\"Sentinel  : v{VERSION} (Puerto {PORT})\\n\".encode(\"utf-8\")\n            + f\"Fecha     : {now}\\n\".encode(\"utf-8\")\n            + \"Atendio   : BLADIMIR (ADMIN) \ud83d\udc64\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + \"2 x \ud83c\udf2e TACOS AL PASTOR      $100.00\\n\".encode(\"utf-8\")\n            + \"  * Con todo y salsa verde\\n\".encode(\"utf-8\")\n            + \"1 x \ud83c\udf7a CERVEZA ARTESANAL    $80.00\\n\".encode(\"utf-8\")\n            + \"1 x \ud83c\udf79 MARGARITA AZUL       $95.50\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + \"SUBTOTAL: $275.50\\n\".encode(\"utf-8\")\n            + \"PROPINA (10%): $27.55\\n\".encode(\"utf-8\")\n            + \"TOTAL: $303.05\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + ESC + b\"a\\x01\"\n            + \"\u00a1Gracias por su preferencia! \u2b50\\n\".encode(\"utf-8\")\n            + \"Facturacion: www.cocinet.app \ud83c\udf10\\n\".encode(\"utf-8\")\n            + \"\\n\\n\\n\"\n            + GS + b\"V\\x41\\x03\"\n        )\n\n        print_data(printer_name, test_bytes, ticket_type=printer_key)\n        log.info(f\"[TEST] Pagina de prueba impresa en '{printer_name}'\")\n        return jsonify({\"success\": True, \"printer_used\": printer_name})\n    except Exception as e:\n        log.error(f\"test-print error: {e}\")\n        return jsonify({\"error\": str(e)}), 500\n\n@app.route(\"/diag-print\", methods=[\"POST\"])\ndef diag_print():\n    logs = []\n    def add_log(msg):\n        timestamp = datetime.now().strftime('%H:%M:%S')\n        full_msg = f\"{timestamp} - {msg}\"\n        logs.append(full_msg)\n        log.info(f\"[DIAG] {msg}\")\n\n    try:\n        data = request.get_json(silent=True) or {}\n        printer_key = data.get(\"printer\", \"cuentas\")\n        add_log(f\"Iniciando diagn\u00f3stico para impresora clave: {printer_key}\")\n\n        printer_name = resolve_printer_name(printer_key)\n        add_log(f\"Impresora resuelta: {printer_name}\")\n\n        ESC = b\"\\x1b\"\n        GS  = b\"\\x1d\"\n        test_bytes = ESC + b\"@\" + b\"Diagnostico OK\\n\" + GS + b\"V\\x41\\x03\"\n\n        add_log(\"Intentando imprimir p\u00e1gina de prueba de diagn\u00f3stico...\")\n        print_data(printer_name, test_bytes, ticket_type=printer_key)\n        add_log(\"Impresi\u00f3n de diagn\u00f3stico completada.\")\n\n        return jsonify({\"success\": True, \"logs\": logs})\n    except Exception as e:\n        err_msg = f\"Error durante diagn\u00f3stico: {str(e)}\"\n        add_log(err_msg)\n        return jsonify({\"success\": False, \"logs\": logs, \"error\": str(e)}), 500\n\n# \u2500\u2500\u2500 Deduplicaci\u00f3n por Hash \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef generar_hash(raw_bytes: bytes) -> str:\n    return hashlib.md5(raw_bytes).hexdigest()\n\ndef check_duplicate_and_register(raw_bytes: bytes, job_id: str = None) -> bool:\n    ticket_hash = generar_hash(raw_bytes)\n    db_path = os.path.join(BASE_DIR, \"restaurant.db\")\n    \n    try:\n        conn = sqlite3.connect(db_path, timeout=30)\n        cursor = conn.cursor()\n        \n        cursor.execute(\"\"\"\n            CREATE TABLE IF NOT EXISTS print_queue (\n                id TEXT PRIMARY KEY,\n                printer_key TEXT NOT NULL,\n                raw_data TEXT NOT NULL,\n                status TEXT NOT NULL DEFAULT 'pending',\n                hash TEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                printed_at TIMESTAMP\n            )\n        \"\"\")\n        conn.commit()\n        \n        cursor.execute(\"\"\"\n            SELECT id FROM print_queue \n            WHERE hash=? AND status='printed' AND printed_at > datetime('now', '-10 seconds')\n        \"\"\", (ticket_hash,))\n        \n        row = cursor.fetchone()\n        if row:\n            if job_id:\n                cursor.execute(\"\"\"\n                    UPDATE print_queue \n                    SET status='duplicate', updated_at=CURRENT_TIMESTAMP \n                    WHERE id=?\n                \"\"\", (job_id,))\n                conn.commit()\n            conn.close()\n            return True\n            \n        if not job_id:\n            new_id = f\"http-{int(time.time() * 1000)}-{ticket_hash[:8]}\"\n            raw_data_encoded = urllib.parse.quote_from_bytes(raw_bytes)\n            cursor.execute(\"\"\"\n                INSERT INTO print_queue (id, printer_key, raw_data, status, hash, printed_at)\n                VALUES (?, 'http_api', ?, 'printed', ?, CURRENT_TIMESTAMP)\n            \"\"\", (new_id, raw_data_encoded, ticket_hash))\n            conn.commit()\n            \n        conn.close()\n        return False\n    except Exception as e:\n        log.error(f\"Error en validaci\u00f3n de deduplicaci\u00f3n: {e}\")\n        return False\n\n# \u2500\u2500\u2500 Polling DB \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef db_polling_loop():\n    db_path = os.path.join(BASE_DIR, \"restaurant.db\")\n    log.info(f\"\ud83d\udd0c Iniciando polling de base de datos en: {db_path}\")\n    while True:\n        try:\n            conn = sqlite3.connect(db_path, timeout=30)\n            cursor = conn.cursor()\n            cursor.execute(\"\"\"\n                CREATE TABLE IF NOT EXISTS print_queue (\n                    id TEXT PRIMARY KEY,\n                    printer_key TEXT NOT NULL,\n                    raw_data TEXT NOT NULL,\n                    status TEXT NOT NULL DEFAULT 'pending',\n                    hash TEXT,\n                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    printed_at TIMESTAMP\n                )\n            \"\"\")\n            conn.commit()\n            conn.close()\n            \n            conn = sqlite3.connect(db_path, timeout=30)\n            conn.execute(\"BEGIN IMMEDIATE\")\n            cursor = conn.cursor()\n            cursor.execute(\"SELECT id, printer_key, raw_data FROM print_queue WHERE status='pending'\")\n            jobs = cursor.fetchall()\n            \n            if jobs:\n                for job_id, _, _ in jobs:\n                    cursor.execute(\"UPDATE print_queue SET status='processing', updated_at=CURRENT_TIMESTAMP WHERE id=?\", (job_id,))\n                conn.commit()\n            else:\n                conn.commit()\n            conn.close()\n            \n            for job_id, printer_key, raw_data in jobs:\n                try:\n                    raw_bytes = urllib.parse.unquote_to_bytes(raw_data)\n                    ticket_hash = generar_hash(raw_bytes)\n                    \n                    if check_duplicate_and_register(raw_bytes, job_id):\n                        log.info(f\"\u26a0\ufe0f Ticket duplicado detectado en cola, no se imprime (ID: {job_id})\")\n                        continue\n                    \n                    printer_name = resolve_printer_name(printer_key)\n                    print_data(printer_name, raw_bytes, ticket_type=printer_key)\n                    \n                    conn2 = sqlite3.connect(db_path, timeout=30)\n                    cursor2 = conn2.cursor()\n                    cursor2.execute(\"\"\"\n                        UPDATE print_queue\n                        SET status='printed', updated_at=CURRENT_TIMESTAMP, printed_at=CURRENT_TIMESTAMP, hash=?\n                        WHERE id=?\n                    \"\"\", (ticket_hash, job_id))\n                    conn2.commit()\n                    conn2.close()\n                    log.info(f\"\u2705 Ticket impreso con \u00e9xito (ID: {job_id}, Impresora: {printer_name})\")\n                    \n                except Exception as ex:\n                    log.error(f\"\u274c Error al procesar trabajo de impresi\u00f3n {job_id}: {ex}\")\n                    conn2 = sqlite3.connect(db_path, timeout=30)\n                    cursor2 = conn2.cursor()\n                    cursor2.execute(\"UPDATE print_queue SET status='failed', updated_at=CURRENT_TIMESTAMP WHERE id=?\", (job_id,))\n                    conn2.commit()\n                    conn2.close()\n            \n            time.sleep(2)\n        except Exception as e:\n            log.error(f\"\u274c Error en bucle de polling: {e}\")\n            time.sleep(5)\n\n# \u2500\u2500\u2500 Servicio Windows \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nclass CocinetPrinterService(win32serviceutil.ServiceFramework):\n    _svc_name_ = \"CocinetPrinterSentinel\"\n    _svc_display_name_ = \"COCINET PRO - Print Sentinel\"\n    _svc_description_ = \"Servidor local HTTP de impresi\u00f3n ESC/POS para COCINET PRO.\"\n\n    def __init__(self, args):\n        win32serviceutil.ServiceFramework.__init__(self, args)\n        self.stop_event = win32event.CreateEvent(None, 0, 0, None)\n\n    def SvcStop(self):\n        log.info(\"Servicio detenido por Windows SCM.\")\n        self.ReportServiceStatus(win32service.SERVICE_STOP_PENDING)\n        stop_flask()\n        win32event.SetEvent(self.stop_event)\n\n    def SvcDoRun(self):\n        servicemanager.LogMsg(\n            servicemanager.EVENTLOG_INFORMATION_TYPE,\n            servicemanager.PYS_SERVICE_STARTED,\n            (self._svc_name_, \"\"),\n        )\n        log.info(\"Servicio iniciado por Windows SCM.\")\n        flask_thread = threading.Thread(target=run_flask, daemon=True)\n        flask_thread.start()\n        win32event.WaitForSingleObject(self.stop_event, win32event.INFINITE)\n\ndef run_flask():\n    db_thread = threading.Thread(target=db_polling_loop, daemon=True)\n    db_thread.start()\n    from werkzeug.serving import make_server\n    global _flask_server\n    _flask_server = make_server(\"0.0.0.0\", PORT, app)\n    log.info(f\"COCINET Print Sentinel v{VERSION} escuchando en puerto {PORT}\")\n    _flask_server.serve_forever()\n\ndef stop_flask():\n    global _flask_server\n    try:\n        _flask_server.shutdown()\n    except Exception:\n        pass\n\ndef run_console():\n    print()\n    print(\"============================================================\")\n    print(\"   COCINET PRO - Windows Print Sentinel  v3.4\")\n    print(\"============================================================\")\n    print(f\"   URL:  http://localhost:{PORT}\")\n    print(f\"   Modo: GDI Vectorial (Arial / Segoe UI)\")\n    print(\"------------------------------------------------------------\")\n    try:\n        installed = get_installed_printers()\n        print(f\"  Impresoras detectadas ({len(installed)}):\")\n        for p in installed:\n            found = any(v.upper() == p.upper() for v in PRINTER_MAP.values())\n            tag   = \"[MAPEADA]   \" if found else \"[disponible]\"\n            print(f\"    {tag}  {p}\")\n    except Exception as e:\n        print(f\"  [WARN] No se pudo listar impresoras: {e}\")\n    print()\n    print(\"  Presiona Ctrl+C para detener.\\n\")\n    try:\n        run_flask()\n    except KeyboardInterrupt:\n        print(\"\\n  Servidor detenido.\")\n\nif __name__ == \"__main__\":\n    if len(sys.argv) == 1:\n        run_console()\n    else:\n        win32serviceutil.HandleCommandLine(CocinetPrinterService)\n";

export const EMBEDDED_INSTALLER_FILES: Record<string, string> = {
  "sentinel_printer.py": "import sys\nimport os\nimport subprocess\nimport importlib\nimport json\n\n# \u2500\u2500\u2500 Directorio base \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nBASE_DIR = os.path.dirname(os.path.abspath(__file__))\n\n# \u2500\u2500\u2500 Dependencias \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nREQUIRED_PACKAGES = {\n    \"flask\": \"Flask\",\n    \"flask_cors\": \"flask-cors\",\n    \"win32print\": \"pywin32\",\n    \"win32serviceutil\": \"pywin32\",\n    \"PIL\": \"Pillow\",\n}\n\ndef ensure_deps():\n    missing = []\n    for module, package in REQUIRED_PACKAGES.items():\n        try:\n            importlib.import_module(module)\n        except ImportError:\n            if package not in missing:\n                missing.append(package)\n    if missing:\n        print(f\"Instalando dependencias faltantes: {missing}\")\n        for pkg in missing:\n            try:\n                subprocess.check_call([sys.executable, \"-m\", \"pip\", \"install\", pkg])\n            except Exception as e:\n                print(f\"Error instalando {pkg}: {e}\")\n\nservice_commands = {\"install\", \"remove\", \"start\", \"stop\", \"restart\", \"debug\", \"update\"}\nrunning_as_service_cmd = len(sys.argv) > 1 and sys.argv[1].lower() in service_commands\nif not running_as_service_cmd or sys.argv[1].lower() == \"debug\":\n    ensure_deps()\n\n# \u2500\u2500\u2500 Importaciones Seguras \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nimport urllib.parse\nimport threading\nimport logging\nimport hashlib\nimport time\nimport sqlite3\nimport re\nfrom datetime import datetime\n\n# Fix DLL search path for pywin32 in elevated UAC environment\ntry:\n    pywin32_sys32 = os.path.join(sys.prefix, \"Lib\", \"site-packages\", \"pywin32_system32\")\n    win32_dir = os.path.join(sys.prefix, \"Lib\", \"site-packages\", \"win32\")\n    sys32_win = os.environ.get(\"SystemRoot\", r\"C:\\Windows\") + r\"\\System32\"\n    for d in (pywin32_sys32, win32_dir, sys32_win):\n        if os.path.exists(d) and hasattr(os, \"add_dll_directory\"):\n            try:\n                os.add_dll_directory(d)\n            except Exception:\n                pass\nexcept Exception:\n    pass\n\ntry:\n    import pywintypes\nexcept Exception:\n    pass\n\nimport win32print\nimport win32serviceutil\nimport win32service\nimport win32event\nimport servicemanager\nimport socket\n\n# PIL\ntry:\n    from PIL import Image, ImageWin\nexcept ImportError:\n    pass\n\nfrom flask import Flask, request, jsonify\nfrom flask_cors import CORS\n\n# \u2500\u2500\u2500 Configuraci\u00f3n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nPORT    = 3010\nVERSION = \"6.0.0\"\n\n# \u2500\u2500\u2500 Helpers Pro: Total en Letra & Detecci\u00f3n de Emojis \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef numero_a_letras(monto: float) -> str:\n    \"\"\"Convierte un monto num\u00e9rico en su representaci\u00f3n formal de texto en espa\u00f1ol (pesos mexicanos M.N.).\"\"\"\n    try:\n        monto = round(float(monto), 2)\n        entero = int(monto)\n        centavos = int(round((monto - entero) * 100))\n\n        UNIDADES = [\"\", \"UN\", \"DOS\", \"TRES\", \"CUATRO\", \"CINCO\", \"SEIS\", \"SIETE\", \"OCHO\", \"NUEVE\"]\n        DECENAS = [\"\", \"DIEZ\", \"VEINTE\", \"TREINTA\", \"CUARENTA\", \"CINCUENTA\", \"SESENTA\", \"SETENTA\", \"OCHENTA\", \"NOVENTA\"]\n        DIEZ_A_DIECINUEVE = [\"DIEZ\", \"ONCE\", \"DOCE\", \"TRECE\", \"CATORCE\", \"QUINCE\", \"DIECISEIS\", \"DIECISIETE\", \"DIECIOCHO\", \"DIECINUEVE\"]\n        CENTENAS = [\"\", \"CIENTO\", \"DOSCIENTOS\", \"TRESCIENTOS\", \"CUATROCIENTOS\", \"QUINIENTOS\", \"SEISCIENTOS\", \"SETECIENTOS\", \"OCHOCIENTOS\", \"NOVECIENTOS\"]\n\n        def _convertir_grupo(n):\n            if n == 0:\n                return \"\"\n            if n == 100:\n                return \"CIEN\"\n            c = n // 100\n            d = (n % 100) // 10\n            u = n % 10\n            texto = CENTENAS[c]\n            res_d = \"\"\n            if d == 1:\n                res_d = DIEZ_A_DIECINUEVE[u]\n            elif d == 2:\n                if u == 0: res_d = \"VEINTE\"\n                else: res_d = f\"VEINTI{UNIDADES[u]}\"\n            elif d > 2:\n                if u == 0: res_d = DECENAS[d]\n                else: res_d = f\"{DECENAS[d]} Y {UNIDADES[u]}\"\n            elif u > 0:\n                res_d = UNIDADES[u]\n\n            if texto and res_d:\n                return f\"{texto} {res_d}\"\n            return texto or res_d\n\n        if entero == 0:\n            texto_entero = \"CERO\"\n        else:\n            partes = []\n            millones = entero // 1_000_000\n            resto = entero % 1_000_000\n            miles = resto // 1_000\n            unidades = resto % 1_000\n\n            if millones > 0:\n                if millones == 1:\n                    partes.append(\"UN MILLON\")\n                else:\n                    partes.append(f\"{_convertir_grupo(millones)} MILLONES\")\n            if miles > 0:\n                if miles == 1:\n                    partes.append(\"UN MIL\")\n                else:\n                    partes.append(f\"{_convertir_grupo(miles)} MIL\")\n            if unidades > 0:\n                partes.append(_convertir_grupo(unidades))\n\n            texto_entero = \" \".join(partes)\n\n        moneda = \"PESO\" if entero == 1 else \"PESOS\"\n        return f\"SON: ({texto_entero} {moneda} {centavos:02d}/100 M.N.)\"\n    except Exception:\n        return \"\"\n\ndef has_emoji(text: str) -> bool:\n    \"\"\"Detecta si el texto contiene caracteres Emojis Unicode.\"\"\"\n    for char in text:\n        code = ord(char)\n        if (0x1F300 <= code <= 0x1F9FF) or (0x2600 <= code <= 0x27BF) or (0x1F600 <= code <= 0x1F64F) or (0x1F680 <= code <= 0x1F6FF):\n            return True\n    return False\n\n# MODO DE IMPRESI\u00d3N PREDETERMINADO: \"gdi\" o \"raw\"\n#   \"gdi\" \u2192 Renderizado gr\u00e1fico con fuentes de Windows (m\u00e1s elegante, profesional y compatible con cualquier tipo de impresora)\n#   \"raw\" \u2192 Env\u00edo de bytes ESC/POS crudos directamente a la impresora\nPRINT_MODE = \"gdi\"\n\n# \u2500\u2500\u2500 Configuraci\u00f3n de Impresoras y Tama\u00f1os de Papel \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nCONFIG_FILE = os.path.join(BASE_DIR, \"printer_config.json\")\n\ndef load_printer_config():\n    default_config = {\n        \"PRINTER_MAP\": {\n            \"cuentas\": \"CUENTAS\",\n            \"cocina\":  \"COCINA\",\n            \"barra\":   \"BARRA\",\n        },\n        \"PRINTER_PAPER_SIZES\": {\n            \"cuentas\": \"80mm\",\n            \"cocina\":  \"80mm\",\n            \"barra\":   \"80mm\",\n        },\n        \"LOGO_PATH\": \"C:\\\\buzon\\\\logo.jpg\",\n        \"FONT_NAME\": \"Segoe UI\",\n        \"FONT_SIZE_PT\": 11.0,\n        \"HEADER_FONT_SIZE_PT\": 16.0,\n        \"ITEM_FONT_SIZE_PT\": 11.0,\n        \"TOTAL_FONT_SIZE_PT\": 15.0,\n        \"MARGIN_LEFT_PX\": 10,\n        \"MARGIN_RIGHT_PX\": 25,\n        \"LINE_SPACING\": 4,\n        \"SHOW_DIVIDER\": True\n    }\n    if os.path.exists(CONFIG_FILE):\n        try:\n            with open(CONFIG_FILE, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n                if \"PRINTER_MAP\" in data and isinstance(data[\"PRINTER_MAP\"], dict):\n                    default_config[\"PRINTER_MAP\"].update(data[\"PRINTER_MAP\"])\n                if \"PRINTER_PAPER_SIZES\" in data and isinstance(data[\"PRINTER_PAPER_SIZES\"], dict):\n                    default_config[\"PRINTER_PAPER_SIZES\"].update(data[\"PRINTER_PAPER_SIZES\"])\n                if \"LOGO_PATH\" in data:\n                    default_config[\"LOGO_PATH\"] = data[\"LOGO_PATH\"]\n                if \"FONT_NAME\" in data:\n                    default_config[\"FONT_NAME\"] = data[\"FONT_NAME\"]\n                if \"FONT_SIZE_PT\" in data:\n                    default_config[\"FONT_SIZE_PT\"] = float(data[\"FONT_SIZE_PT\"])\n                if \"HEADER_FONT_SIZE_PT\" in data:\n                    default_config[\"HEADER_FONT_SIZE_PT\"] = float(data[\"HEADER_FONT_SIZE_PT\"])\n                if \"ITEM_FONT_SIZE_PT\" in data:\n                    default_config[\"ITEM_FONT_SIZE_PT\"] = float(data[\"ITEM_FONT_SIZE_PT\"])\n                if \"TOTAL_FONT_SIZE_PT\" in data:\n                    default_config[\"TOTAL_FONT_SIZE_PT\"] = float(data[\"TOTAL_FONT_SIZE_PT\"])\n                if \"MARGIN_LEFT_PX\" in data:\n                    default_config[\"MARGIN_LEFT_PX\"] = int(data[\"MARGIN_LEFT_PX\"])\n                if \"MARGIN_RIGHT_PX\" in data:\n                    default_config[\"MARGIN_RIGHT_PX\"] = int(data[\"MARGIN_RIGHT_PX\"])\n                if \"LINE_SPACING\" in data:\n                    default_config[\"LINE_SPACING\"] = int(data[\"LINE_SPACING\"])\n                if \"SHOW_DIVIDER\" in data:\n                    default_config[\"SHOW_DIVIDER\"] = bool(data[\"SHOW_DIVIDER\"])\n        except Exception as e:\n            print(f\"Error cargando config de impresoras: {e}\")\n    else:\n        try:\n            with open(CONFIG_FILE, \"w\", encoding=\"utf-8\") as f:\n                json.dump(default_config, f, indent=4, ensure_ascii=False)\n        except Exception:\n            pass\n    return default_config\n\nconfig_printers = load_printer_config()\nPRINTER_MAP = config_printers[\"PRINTER_MAP\"]\nPRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\nLOGO_PATH = config_printers[\"LOGO_PATH\"]\nFONT_NAME = config_printers[\"FONT_NAME\"]\nFONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n# \u2500\u2500\u2500 Flask app \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\napp = Flask(__name__)\nCORS(app)\napp.logger.disabled = True\nlog_flask = logging.getLogger(\"werkzeug\")\nlog_flask.setLevel(logging.ERROR)\n\ndef sanitize_text(text: str) -> str:\n    \"\"\"Remueve cualquier caracter de control binario residual de ESC/POS (como \\x1b, \\x1d, LE1, E1, etc.).\"\"\"\n    if not text:\n        return \"\"\n    # Remover secuencias residuales comunes de ESC/POS\n    text = re.sub(r'[\\x00-\\x1f\\x7f-\\x9f]', '', text)\n    text = re.sub(r'(?:LE[01]|E[01]|!\\d+)', '', text)\n    return text.strip()\n\nLOG_FILE = os.path.join(BASE_DIR, \"sentinel_printer.log\")\n\ndef get_logger():\n    logger = logging.getLogger(\"sentinel\")\n    if logger.handlers:\n        return logger\n    logger.setLevel(logging.INFO)\n    fmt = logging.Formatter(\"%(asctime)s [%(levelname)s] %(message)s\", \"%Y-%m-%d %H:%M:%S\")\n    fh = logging.FileHandler(LOG_FILE, encoding=\"utf-8\")\n    fh.setFormatter(fmt)\n    logger.addHandler(fh)\n    if sys.stdout and sys.stdout.isatty():\n        ch = logging.StreamHandler(sys.stdout)\n        ch.setFormatter(fmt)\n        logger.addHandler(ch)\n    return logger\n\nlog = get_logger()\n\n# \u2500\u2500\u2500 Parser de Comandos ESC/POS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef parse_escpos(raw_bytes: bytes) -> list:\n    \"\"\"\n    Decodifica un flujo de bytes ESC/POS y lo convierte en una lista de l\u00edneas estructuradas\n    con propiedades de alineaci\u00f3n, tama\u00f1o de fuente y negritas para su renderizado GDI.\n    \"\"\"\n    lines = []\n    current_line_text = \"\"\n    \n    align = 0  # 0=izq, 1=centro, 2=der\n    bold = False\n    size = 'normal'  # 'normal', 'big', 'small'\n\n    def flush_current():\n        nonlocal current_line_text\n        if current_line_text.strip():\n            lines.append({\n                'text': current_line_text.strip(),\n                'align': align,\n                'size': size,\n                'bold': bold\n            })\n            current_line_text = \"\"\n    \n    i = 0\n    n = len(raw_bytes)\n    \n    while i < n:\n        b = raw_bytes[i]\n        \n        # Comando ESC (0x1b / 27)\n        if b == 0x1b:\n            if i + 1 < n:\n                cmd = raw_bytes[i + 1]\n                # ESC @ (Inicializar impresora)\n                if cmd == 0x40:\n                    flush_current()\n                    align = 0\n                    bold = False\n                    size = 'normal'\n                    i += 2\n                    continue\n                # ESC a (Alineaci\u00f3n)\n                elif cmd == 0x61:\n                    if i + 2 < n:\n                        flush_current()\n                        align = raw_bytes[i + 2]\n                        i += 3\n                        continue\n                # ESC ! (Modo de impresi\u00f3n general)\n                elif cmd == 0x21:\n                    if i + 2 < n:\n                        mode = raw_bytes[i + 2]\n                        new_bold = bool(mode & 8)\n                        new_size = 'big' if (mode & 48) else 'normal'\n                        if new_bold != bold or new_size != size:\n                            flush_current()\n                            bold = new_bold\n                            size = new_size\n                        i += 3\n                        continue\n                # ESC E (Negrita)\n                elif cmd == 0x45:\n                    if i + 2 < n:\n                        new_bold = bool(raw_bytes[i + 2])\n                        if new_bold != bold:\n                            flush_current()\n                            bold = new_bold\n                        i += 3\n                        continue\n                # ESC d (Avanzar N l\u00edneas)\n                elif cmd == 0x64:\n                    if i + 2 < n:\n                        feed_count = raw_bytes[i + 2]\n                        flush_current()\n                        for _ in range(max(1, feed_count - 1)):\n                            lines.append({\n                                'text': '',\n                                'align': align,\n                                'size': size,\n                                'bold': bold\n                            })\n                        i += 3\n                        continue\n                # Descartar otros comandos ESC de 2 o 3 bytes\n                elif cmd in (0x4a, 0x33, 0x32, 0x4d, 0x7b, 0x56):\n                    i += 3\n                    continue\n            i += 2\n            continue\n            \n        # Comando GS (0x1d / 29)\n        elif b == 0x1d:\n            if i + 1 < n:\n                cmd = raw_bytes[i + 1]\n                # GS V (Corte de papel)\n                if cmd == 0x56:\n                    if i + 2 < n and raw_bytes[i + 2] in (65, 66):\n                        i += 4\n                        continue\n                    else:\n                        i += 3\n                        continue\n                elif cmd in (0x21, 0x42, 0x6b, 0x77, 0x68):\n                    i += 3\n                    continue\n            i += 2\n            continue\n            \n        # Salto de l\u00ednea (LF = 0x0a / 10)\n        elif b == 0x0a:\n            flush_current()\n            i += 1\n            \n        # Retorno de carro (CR = 0x0d / 13)\n        elif b == 0x0d:\n            if i + 1 < n and raw_bytes[i + 1] == 0x0a:\n                i += 1\n            else:\n                flush_current()\n                i += 1\n            \n        # Caracteres normales del ticket\n        else:\n            decoded = False\n            # Intentar decodificar secuencias UTF-8 multibyte (hasta 4 bytes) para preservar Emojis (\ud83c\udf2e, \ud83c\udf7a, \ud83d\udd14, \ud83d\udcb0, etc.)\n            for length in (4, 3, 2, 1):\n                if i + length <= n:\n                    try:\n                        char_str = raw_bytes[i:i+length].decode('utf-8')\n                        current_line_text += char_str\n                        i += length\n                        decoded = True\n                        break\n                    except UnicodeDecodeError:\n                        continue\n            if not decoded:\n                try:\n                    char_str = raw_bytes[i:i+1].decode('cp850')\n                except Exception:\n                    char_str = chr(b)\n                current_line_text += char_str\n                i += 1\n            \n    flush_current()\n        \n    # Sanitizar todas las l\u00edneas para remover basura binaria\n    cleaned_lines = []\n    for l in lines:\n        cleaned_text = sanitize_text(l['text'])\n        if cleaned_text or l['text'] == '':\n            cleaned_lines.append({**l, 'text': cleaned_text})\n\n    return cleaned_lines\n\n# \u2500\u2500\u2500 Motores de Impresi\u00f3n \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef get_installed_printers() -> list:\n    flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS\n    return [p[2] for p in win32print.EnumPrinters(flags)]\n\ndef resolve_printer_name(key: str) -> str:\n    global PRINTER_MAP\n    try:\n        config_printers = load_printer_config()\n        PRINTER_MAP = config_printers.get(\"PRINTER_MAP\", PRINTER_MAP)\n    except Exception:\n        pass\n        \n    target = PRINTER_MAP.get(key.lower(), key)\n    installed = get_installed_printers()\n    if not installed:\n        raise ValueError(\"No hay impresoras instaladas en el sistema Windows.\")\n        \n    # 1. Coincidencia exacta\n    for p in installed:\n        if p.upper() == target.upper():\n            return p\n            \n    # 2. Coincidencia parcial (subcadena)\n    for p in installed:\n        if target.upper() in p.upper() or p.upper() in target.upper():\n            return p\n            \n    # 3. Fallback a la impresora predeterminada de Windows\n    try:\n        default_win = win32print.GetDefaultPrinter()\n        if default_win in installed:\n            log.info(f\"\u26a0\ufe0f Impresora '{target}' no mapeada expl\u00edcitamente. Redirigiendo a la predeterminada de Windows: '{default_win}'\")\n            return default_win\n    except Exception:\n        pass\n        \n    # 4. Fallback a la primera impresora instalada\n    first_printer = installed[0]\n    log.info(f\"\u26a0\ufe0f Impresora '{target}' no encontrada. Redirigiendo a la primera impresora disponible: '{first_printer}'\")\n    return first_printer\n\ndef send_raw_to_printer(printer_name: str, data_bytes: bytes):\n    hPrinter = win32print.OpenPrinter(printer_name)\n    try:\n        job_name = f\"COCINET-RAW-{datetime.now().strftime('%H%M%S')}\"\n        win32print.StartDocPrinter(hPrinter, 1, (job_name, None, \"RAW\"))\n        try:\n            win32print.StartPagePrinter(hPrinter)\n            win32print.WritePrinter(hPrinter, data_bytes)\n            win32print.EndPagePrinter(hPrinter)\n        finally:\n            win32print.EndDocPrinter(hPrinter)\n    finally:\n        win32print.ClosePrinter(hPrinter)\n\ndef draw_logo_on_dc(hDC, logo_path: str, printable_width: int, y_start: int, dpi_y: int) -> int:\n    \"\"\"Carga y dibuja el logotipo centrado en el DC del ticket, retornando la nueva coordenada Y.\"\"\"\n    target_logo = None\n    possible_paths = [\n        logo_path,\n        \"C:\\\\buzon\\\\logoroy.png\",\n        \"C:\\\\buzon\\\\logo.png\",\n        \"C:\\\\buzon\\\\logo.jpg\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logoroy.png\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logo.png\",\n        \"C:\\\\buzon\\\\INSTALADOR_SENTINELA\\\\logo.jpg\",\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logoroy.png\"),\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logo.png\"),\n        os.path.join(os.path.dirname(os.path.abspath(__file__)), \"logo.jpg\"),\n    ]\n    for p in possible_paths:\n        if p and os.path.exists(p):\n            target_logo = p\n            break\n\n    if not target_logo:\n        log.warning(\"No se encontr\u00f3 logotipo f\u00edsico en ninguna de las rutas de b\u00fasqueda.\")\n        return y_start\n\n    try:\n        from PIL import Image, ImageWin\n        img = Image.open(target_logo)\n        if img.mode != \"RGB\":\n            img = img.convert(\"RGB\")\n            \n        w, h = img.size\n        max_logo_width = int(printable_width * 0.45)\n        scale = max_logo_width / float(w)\n        new_w = max_logo_width\n        new_h = int(h * scale)\n        \n        img = img.resize((new_w, new_h), Image.Resampling.LANCZOS)\n        margin_left = 25\n        x_start = margin_left + max(0, (printable_width - new_w) // 2)\n        \n        hdc_handle = hDC.GetSafeHdc()\n        dib = ImageWin.Dib(img)\n        dib.draw(hdc_handle, (x_start, y_start, x_start + new_w, y_start + new_h))\n        return y_start + new_h + 15\n    except Exception as e:\n        log.error(f\"Error renderizando el logotipo GDI ({target_logo}): {e}\")\n        return y_start\n\ndef wrap_and_draw_text(hDC, text: str, margin_left: int, margin_right: int, printable_width: int, y: int, align: int = 0, line_spacing: int = 4) -> int:\n    \"\"\"Renderiza texto con ajuste de l\u00ednea autom\u00e1tico para evitar recortes en los bordes del papel.\"\"\"\n    if not text:\n        return y\n        \n    text_w, text_h = hDC.GetTextExtent(text)\n    if text_w <= printable_width:\n        if align == 1:    # Centro\n            x = margin_left + (printable_width - text_w) // 2\n        elif align == 2:  # Derecha\n            x = margin_left + printable_width - text_w\n        else:             # Izquierda\n            x = margin_left\n        hDC.TextOut(x, y, text)\n        return y + text_h + line_spacing\n\n    words = text.split(\" \")\n    lines_to_draw = []\n    curr_line = \"\"\n    \n    for word in words:\n        test_line = f\"{curr_line} {word}\".strip() if curr_line else word\n        w, _ = hDC.GetTextExtent(test_line)\n        if w <= printable_width:\n            curr_line = test_line\n        else:\n            if curr_line:\n                lines_to_draw.append(curr_line)\n            w_word, _ = hDC.GetTextExtent(word)\n            if w_word > printable_width:\n                sub = \"\"\n                for char in word:\n                    if hDC.GetTextExtent(sub + char)[0] <= printable_width:\n                        sub += char\n                    else:\n                        lines_to_draw.append(sub)\n                        sub = char\n                curr_line = sub\n            else:\n                curr_line = word\n                \n    if curr_line:\n        lines_to_draw.append(curr_line)\n        \n    for l_text in lines_to_draw:\n        tw, th = hDC.GetTextExtent(l_text)\n        if align == 1:    # Centro\n            x = margin_left + (printable_width - tw) // 2\n        elif align == 2:  # Derecha\n            x = margin_left + printable_width - tw\n        else:             # Izquierda\n            x = margin_left\n        hDC.TextOut(x, y, l_text)\n        y += th + line_spacing\n        \n    return y\n\ndef send_gdi_to_printer(printer_name: str, data_bytes: bytes, ticket_type: str = \"comanda\"):\n    \"\"\"Parsea el ticket de comandos ESC/POS y lo dibuja vectorialmente usando el GDI de Windows.\"\"\"\n    import pywintypes\n    import win32ui\n    import win32con\n\n    global PRINTER_MAP, PRINTER_PAPER_SIZES, LOGO_PATH, FONT_NAME, FONT_SIZE_PT\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n    PRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\n    LOGO_PATH = config_printers[\"LOGO_PATH\"]\n    FONT_NAME = config_printers[\"FONT_NAME\"]\n    FONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n    parsed_lines = parse_escpos(data_bytes)\n    \n    printer_key = \"cuentas\"\n    for k, v in PRINTER_MAP.items():\n        if v.upper() == printer_name.upper():\n            printer_key = k\n            break\n            \n    paper_size = PRINTER_PAPER_SIZES.get(printer_key, \"80mm\")\n    \n    hDC = win32ui.CreateDC()\n    hDC.CreatePrinterDC(printer_name)\n    hDC.SetMapMode(win32con.MM_TEXT)\n    hDC.SetBkMode(win32con.TRANSPARENT)\n    \n    dpi_y = hDC.GetDeviceCaps(win32con.LOGPIXELSY) or 203\n    \n    # Obtener el ancho real de la superficie de impresi\u00f3n informada por el driver de Windows (DC)\n    dev_width = hDC.GetDeviceCaps(win32con.HORZRES) or hDC.GetDeviceCaps(win32con.PHYSICALWIDTH)\n    if dev_width and dev_width > 150:\n        width = dev_width\n    else:\n        width = 370 if paper_size == \"58mm\" else 540\n        \n    margin_left = 15 if paper_size == \"58mm\" else 25\n    margin_right = 15 if paper_size == \"58mm\" else 25\n    printable_width = width - margin_left - margin_right\n    job_name = f\"COCINET-GDI-{paper_size}-{datetime.now().strftime('%H%M%S')}\"\n    hDC.StartDoc(job_name)\n    hDC.StartPage()\n    \n    font_cache = {}\n    \n    def get_font(name, pt_size, is_bold, is_italic=False, use_emoji_font=False):\n        font_name_to_use = \"Segoe UI Emoji\" if (use_emoji_font or name == \"Segoe UI Emoji\") else name\n        key = (font_name_to_use, pt_size, is_bold, is_italic)\n        if key in font_cache:\n            return font_cache[key]\n        height = int(pt_size * dpi_y / 72)\n        f = win32ui.CreateFont({\n            \"name\": font_name_to_use,\n            \"height\": height,\n            \"weight\": win32con.FW_BOLD if is_bold else win32con.FW_NORMAL,\n            \"italic\": is_italic,\n            \"charset\": win32con.DEFAULT_CHARSET\n        })\n        font_cache[key] = f\n        return f\n\n    y = 20\n    \n    # Dibujar logotipo para todos los tickets comerciales (cuentas/precuentas/caja)\n    if ticket_type.lower() not in [\"cocina\", \"barra\"]:\n        y = draw_logo_on_dc(hDC, LOGO_PATH, width, y, dpi_y)\n    \n    # Escalar tama\u00f1o base de tipograf\u00eda\n    base_pt = FONT_SIZE_PT\n    if paper_size == \"58mm\":\n        base_pt = base_pt * 0.82\n        \n    # Pre-procesamiento: separar renglones concatenados (ej: m\u00faltiples productos pegados o SUBTOTAL y TOTAL)\n    expanded_lines = []\n    for l in parsed_lines:\n        txt = l['text'].strip()\n        if not txt:\n            expanded_lines.append(l)\n            continue\n            \n        # 1. Separar si vienen m\u00faltiples productos concatenados en una sola l\u00ednea (ej: \"6x TACO DE PASTOR (MA\u00cdZ) $132.002x REFRESCOS $76.00\")\n        item_split_pattern = r'(\\d+\\s*(?:x|X)\\s+.*?(?:\\$?[0-9]+(?:\\.[0-9]{1,2})?)(?=\\s*\\d+\\s*(?:x|X)\\s+|$))'\n        found_items = re.findall(item_split_pattern, txt, flags=re.IGNORECASE)\n        if len(found_items) > 1:\n            for item_str in found_items:\n                if item_str.strip():\n                    expanded_lines.append({**l, 'text': item_str.strip()})\n            continue\n\n        # 2. Evitar recortar 'SUBTOTAL' en 'SUB' + 'TOTAL' usando Lookbehind Negativo (?<!SUB)\n        keywords_pattern = r'(?=(?:RFC|SUC|FOLIO|REIMPRESION|PRECUENTA|MESA|FECHA|HORA|PAGO|SUBTOTAL|(?<!SUB)TOTAL|PROPINA|DESCUENTO|CAMBIO)\\s*:)'\n        found_parts = re.split(keywords_pattern, txt, flags=re.IGNORECASE)\n        if len(found_parts) > 1:\n            for p in found_parts:\n                if p.strip():\n                    expanded_lines.append({**l, 'text': p.strip()})\n        else:\n            expanded_lines.append(l)\n\n    header_drawn = False\n    in_table_phase = False\n    header_metadata_passed = False\n        \n    for line in expanded_lines:\n        text = line['text'].strip()\n        alignment = line['align']\n        size_mode = line['size']\n        is_bold = line['bold']\n        line_has_emoji = has_emoji(text)\n        \n        # 1. L\u00edneas divisorias vectoriales elegantes\n        if len(text) >= 10 and all(c in ('-', '=', '_', '*') for c in text):\n            pen = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x94a3b8)\n            hDC.SelectObject(pen)\n            hDC.MoveTo(margin_left, y + 5)\n            hDC.LineTo(width - margin_right, y + 5)\n            y += 14\n            continue\n            \n        # 2. Renglon vac\u00edo\n        if not text:\n            f = get_font(FONT_NAME, base_pt, False)\n            hDC.SelectObject(f)\n            _, text_height = hDC.GetTextExtent(\" \")\n            y += text_height\n            continue\n            \n        # Determinar el tama\u00f1o de tipograf\u00eda (pt)\n        if size_mode == 'big':\n            pt = base_pt * 1.30\n            bold_to_use = True\n        elif size_mode == 'small':\n            pt = base_pt * 0.75\n            bold_to_use = is_bold\n        else:\n            pt = base_pt\n            bold_to_use = is_bold\n            \n        f = get_font(FONT_NAME, pt, bold_to_use, use_emoji_font=line_has_emoji)\n        hDC.SelectObject(f)\n\n        # 3. Detectar Rengl\u00f3n de Producto (requiere prefijo de cantidad \"1x\", \"6x\" o importe final \"$XX.XX\")\n        EXCLUDED_KEYS = [\"MESA\", \"HORA\", \"FOLIO\", \"FECHA\", \"COMANDA\", \"SUBTOTAL\", \"TOTAL\", \"PROPINA\", \"DESCUENTO\", \"DIR:\", \"TEL:\", \"EMAIL:\", \"CLIENTE:\", \"ATENDIO\", \"MESERO\", \"REIMPRESION\", \"CUENTA\", \"PRECUENTA\", \"SUC:\", \"RFC:\", \"REGIMEN\", \"R\u00c9GIMEN\", \"LUGAR\", \"EXPEDICION\", \"EXPEDICI\u00d3N\", \"FORMA DE PAGO\", \"PAGA CON\", \"RECIBIDO\", \"CAMBIO\", \"DATOS DE ENVIO\", \"SON:\", \"PAGADO\", \"EFECTIVO\", \"TARJETA\", \"TRANSFERENCIA\", \"DESTINO:\", \"GRACIAS\", \"VISITA\", \"VUELVA\", \"OBS:\"]\n        \n        has_qty = bool(re.match(r'^\\s*\\d+\\s*(?:x|X)?\\s+', text, re.IGNORECASE))\n        has_price = bool(re.search(r'\\$?([0-9]+(?:[\\.,][0-9]{1,2})?)\\s*$', text))\n        \n        # El rengl\u00f3n de producto se identifica de forma absoluta por tener cantidad inicial o importe final sin ser clave de cabecera\n        is_item_line = bool(\n            (has_qty or has_price) and\n            not any(text.upper().startswith(k) for k in EXCLUDED_KEYS) and\n            not any(c in ('-', '=', '_', '*') for c in text)\n        )\n\n        log.info(f\"  [GDI v5.0.0]: '{text}' | item={is_item_line}\")\n\n        # Dibujar encabezado de tabla estilizada justo despu\u00e9s de los metadatos y antes del primer producto\n        if is_item_line and not header_drawn and ticket_type.lower() in [\"cuentas\", \"cuenta\", \"precuenta\"]:\n            header_drawn = True\n            in_table_phase = True\n            \n            # Espaciado vectorial para bajar la tabla y dejarla clara debajo de MESA/FECHA\n            y += 6\n            \n            # L\u00ednea superior del encabezado de tabla\n            pen_tbl = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x334155)\n            hDC.SelectObject(pen_tbl)\n            hDC.MoveTo(margin_left, y + 2)\n            hDC.LineTo(width - margin_right, y + 2)\n            y += 8\n            \n            # Encabezado de 1 rengl\u00f3n: CANT / DESCRIPCI\u00d3N                IMPORTE\n            fh = get_font(FONT_NAME, base_pt * 0.88, True)\n            hDC.SelectObject(fh)\n            hDC.TextOut(margin_left, y, \"CANT / DESCRIPCI\u00d3N\")\n            w_imp, h_imp = hDC.GetTextExtent(\"IMPORTE\")\n            x_imp = max(margin_left + 150, width - margin_right - w_imp)\n            hDC.TextOut(x_imp, y, \"IMPORTE\")\n            y += h_imp + 4\n            \n            # L\u00ednea inferior del encabezado\n            hDC.MoveTo(margin_left, y + 2)\n            hDC.LineTo(width - margin_right, y + 2)\n            y += 10\n\n        # Renderizar Rengl\u00f3n de Producto (1 solo rengl\u00f3n estricto por producto, truncando la descripci\u00f3n si es muy larga)\n        if is_item_line:\n            desc = text.strip()\n            price_str = None\n            qty_str = None\n            \n            # 1. Extraer precio al final de la l\u00ednea si existe\n            p_m = re.search(r'\\$?([0-9]+(?:\\.[0-9]{1,2})?)\\s*$', desc)\n            if p_m:\n                price_str = p_m.group(1)\n                desc = desc[:p_m.start()].strip()\n                \n            # 2. Extraer cantidad al inicio si existe\n            q_m = re.match(r'^\\s*(\\d+)\\s*(?:x|X)?\\s+(.*)$', desc, re.IGNORECASE)\n            if q_m:\n                qty_str = q_m.group(1)\n                desc = q_m.group(2).strip()\n                \n            qty_val = int(qty_str) if (qty_str and qty_str.isdigit()) else 1\n            price_num = float(price_str.replace(',', '')) if price_str else 0.0\n            \n            # 3. Dibujar el IMPORTE alineado a la derecha en la misma l\u00ednea\n            imp_str = f\"${price_num:.2f}\" if price_num > 0 else \"\"\n            fp = get_font(FONT_NAME, pt * 0.95, True)\n            hDC.SelectObject(fp)\n            \n            if imp_str:\n                pr_w, pr_h = hDC.GetTextExtent(imp_str)\n                x_right = max(margin_left + 120, width - margin_right - pr_w)\n                hDC.TextOut(x_right, y, imp_str)\n            else:\n                pr_w, pr_h = 0, int(pt * dpi_y / 72)\n                x_right = width - margin_right\n                \n            # 4. Formatear la descripci\u00f3n limpia con su cantidad (ej: \"1x TACO DE PASTOR (MA\u00cdZ)\")\n            full_desc_left = f\"{qty_val}x {desc}\"\n                \n            # 5. Truncar la descripci\u00f3n si excede el espacio disponible antes del importe\n            fd = get_font(FONT_NAME, pt * 0.95, True, use_emoji_font=has_emoji(full_desc_left))\n            hDC.SelectObject(fd)\n            \n            max_desc_w = x_right - margin_left - 10\n            curr_desc = full_desc_left\n            \n            if max_desc_w > 40:\n                while curr_desc and hDC.GetTextExtent(curr_desc)[0] > max_desc_w:\n                    curr_desc = curr_desc[:-1]\n                if len(curr_desc) < len(full_desc_left):\n                    curr_desc = curr_desc.rstrip() + \"...\"\n            \n            hDC.TextOut(margin_left, y, curr_desc)\n            _, desc_h = hDC.GetTextExtent(curr_desc)\n            \n            y += max(desc_h, pr_h, int(pt * dpi_y / 72)) + 5\n            continue\n        \n        # 3.5. Formatear y renderizar Fecha y Hora con Emojis \ud83d\udcc5 y \u23f0 (Negrita, oscuro y legible)\n        if text.upper().startswith(\"FECHA:\") or text.upper().startswith(\"HORA:\") or \"FECHA:\" in text.upper():\n            clean_date_text = text\n            if \"FECHA:\" in clean_date_text.upper():\n                date_val = re.sub(r'^FECHA:\\s*', '', clean_date_text, flags=re.IGNORECASE).strip()\n                if ',' in date_val:\n                    parts = date_val.split(',', 1)\n                    f_part = parts[0].strip()\n                    h_part = parts[1].strip()\n                    formatted_dt = f\"\ud83d\udcc5 {f_part}   \u23f0 {h_part}\"\n                else:\n                    formatted_dt = f\"\ud83d\udcc5 {date_val}\"\n            elif clean_date_text.upper().startswith(\"HORA:\"):\n                hora_val = clean_date_text[5:].strip()\n                formatted_dt = f\"\u23f0 {hora_val}\"\n            else:\n                formatted_dt = text\n\n            f_dt = get_font(FONT_NAME, pt * 1.05, True, use_emoji_font=True)\n            hDC.SelectObject(f_dt)\n            y = wrap_and_draw_text(hDC, formatted_dt, margin_left, margin_right, printable_width, y, align=0, line_spacing=4)\n            continue\n        \n        # 4. Formatear y alinear Totales, Subtotales, Cambios, etc.\n        total_match = re.search(r'^(TOTAL A PAGAR|TOTAL|SUBTOTAL|SUMA TOTAL|PROPINA MESEROS|PROPINA VOLUNTARIA|PROPINA|DESCUENTO|FORMA DE PAGO|PAGO|PAGA CON|RECIBIDO|CAMBIO|ATENDIDO POR|MESERO|MESA)\\s*:?\\s*(.*)$', text, re.IGNORECASE)\n        has_total_keyword = bool(total_match or (\"TOTAL\" in text.upper() and \"SUBTOTAL\" not in text.upper()))\n        \n        if has_total_keyword:\n            if in_table_phase:\n                in_table_phase = False\n                pen_end = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x334155)\n                hDC.SelectObject(pen_end)\n                hDC.MoveTo(margin_left, y + 2)\n                hDC.LineTo(width - margin_right, y + 2)\n                y += 12\n\n            if total_match:\n                label = total_match.group(1).upper() + \":\"\n                val = total_match.group(2).strip()\n            else:\n                parts = text.split(\":\", 1)\n                label = parts[0].strip().upper() + \":\"\n                val = parts[1].strip() if len(parts) > 1 else \"\"\n\n            is_total_label = (\"TOTAL\" in label or \"TOTAL\" in text.upper()) and \"SUBTOTAL\" not in text.upper()\n            \n            lbl_pt = pt * 1.15 if is_total_label else pt\n            lbl_str = \"TOTAL A PAGAR:\" if is_total_label else label\n            fl = get_font(FONT_NAME, lbl_pt, is_total_label or is_bold, use_emoji_font=has_emoji(lbl_str))\n            hDC.SelectObject(fl)\n            \n            # Posicionar etiquetas al margen izquierdo para evitar colisi\u00f3n con importes a la derecha\n            lbl_w, lbl_h = hDC.GetTextExtent(lbl_str)\n            x_lbl = margin_left\n            hDC.TextOut(x_lbl, y, lbl_str)\n            \n            val_pt = pt * 1.25 if is_total_label else pt\n            fb = get_font(FONT_NAME, val_pt, True, use_emoji_font=has_emoji(val))\n            hDC.SelectObject(fb)\n            val_width, val_height = hDC.GetTextExtent(val)\n            x_val = max(margin_left + lbl_w + 10, width - margin_right - val_width)\n            hDC.TextOut(x_val, y, val)\n            y += max(lbl_h, val_height) + 6\n            \n            # SI ES EL TOTAL PRINCIPAL, DIBUJAR AUTOM\u00c1TICAMENTE EL TOTAL EN LETRA DEBAJO\n            if is_total_label:\n                monto_match = re.search(r'([0-9.,]+)', val)\n                if monto_match:\n                    try:\n                        monto_clean = float(monto_match.group(1).replace(',', ''))\n                        letra_str = numero_a_letras(monto_clean)\n                        if letra_str:\n                            f_letra = get_font(FONT_NAME, base_pt * 0.82, True, is_italic=True, use_emoji_font=has_emoji(letra_str))\n                            hDC.SelectObject(f_letra)\n                            y = wrap_and_draw_text(hDC, letra_str, margin_left, margin_right, printable_width, y, align=1, line_spacing=3)\n                            \n                            pen_tot = win32ui.CreatePen(win32con.PS_SOLID, 2, 0x475569)\n                            hDC.SelectObject(pen_tot)\n                            hDC.MoveTo(margin_left, y + 2)\n                            hDC.LineTo(width - margin_right, y + 2)\n                            y += 12\n                    except Exception as e:\n                        log.error(f\"Error calculando total en letra: {e}\")\n            continue\n\n        # 5. Renderizar notas del producto (l\u00edneas con asterisco *) con it\u00e1licas e indentadas\n        if text.startswith('*') or text.startswith('>'):\n            f_italic = get_font(FONT_NAME, pt, False, is_italic=True, use_emoji_font=has_emoji(text))\n            hDC.SelectObject(f_italic)\n            y = wrap_and_draw_text(hDC, text, margin_left + 40, margin_right, printable_width - 40, y, align=0, line_spacing=3)\n            continue\n            \n        # 6. Renderizar l\u00edneas comunes y pie de p\u00e1gina con envoltorio autom\u00e1tico\n        f_line = get_font(FONT_NAME, pt, bold_to_use, use_emoji_font=line_has_emoji)\n        hDC.SelectObject(f_line)\n        y = wrap_and_draw_text(hDC, text, margin_left, margin_right, printable_width, y, align=alignment, line_spacing=4)\n        \n    hDC.EndPage()\n    hDC.EndDoc()\n    hDC.DeleteDC()\n\ndef print_data(printer_name: str, data_bytes: bytes, ticket_type: str = \"comanda\"):\n    \"\"\"Bypass unificado para imprimir en RAW o renderizar vectorialmente en GDI.\"\"\"\n    if PRINT_MODE.lower() == \"gdi\":\n        try:\n            log.info(f\"Imprimiendo v\u00eda GDI vectorial ({ticket_type}) en: '{printer_name}'\")\n            send_gdi_to_printer(printer_name, data_bytes, ticket_type)\n        except Exception as e:\n            log.error(f\"Fallo en GDI: {e}. Reintentando con bypass RAW...\")\n            send_raw_to_printer(printer_name, data_bytes)\n    else:\n        send_raw_to_printer(printer_name, data_bytes)\n\n# \u2500\u2500\u2500 Endpoints de Flask \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n@app.route(\"/config\", methods=[\"GET\", \"POST\"])\ndef manage_config():\n    if request.method == \"POST\":\n        try:\n            data = request.get_json(silent=True) or {}\n            current = load_printer_config()\n            current.update(data)\n            with open(CONFIG_FILE, \"w\", encoding=\"utf-8\") as f:\n                json.dump(current, f, indent=4, ensure_ascii=False)\n            load_printer_config()\n            return jsonify({\"success\": True, \"config\": current})\n        except Exception as e:\n            return jsonify({\"success\": False, \"error\": str(e)}), 500\n    else:\n        cfg = load_printer_config()\n        return jsonify({\"success\": True, \"config\": cfg})\n\n@app.route(\"/download/<filename>\", methods=[\"GET\"])\ndef download_sentinel_file(filename):\n    safe_files = [\"sentinel_printer.py\", \"instalador.bat\", \"instalador_sentinela.py\", \"printer_config.json\"]\n    if filename not in safe_files:\n        return jsonify({\"error\": \"File not allowed\"}), 400\n    file_path = os.path.join(BASE_DIR, filename)\n    if not os.path.exists(file_path):\n        return jsonify({\"error\": \"File not found\"}), 404\n    from flask import send_file\n    return send_file(file_path, as_attachment=True)\n\n@app.route(\"/status\", methods=[\"GET\"])\ndef get_status():\n    global PRINTER_MAP, PRINTER_PAPER_SIZES, LOGO_PATH, FONT_NAME, FONT_SIZE_PT\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n    PRINTER_PAPER_SIZES = config_printers[\"PRINTER_PAPER_SIZES\"]\n    LOGO_PATH = config_printers[\"LOGO_PATH\"]\n    FONT_NAME = config_printers[\"FONT_NAME\"]\n    FONT_SIZE_PT = config_printers[\"FONT_SIZE_PT\"]\n\n    installed = get_installed_printers()\n    mapped = {\n        key: {\n            \"windows_name\": win_name,\n            \"paper_size\": PRINTER_PAPER_SIZES.get(key, \"80mm\"),\n            \"available\": any(p.upper() == win_name.upper() for p in installed),\n        }\n        for key, win_name in PRINTER_MAP.items()\n    }\n    return jsonify({\n        \"status\": \"online\",\n        \"service\": \"COCINET Print Sentinel\",\n        \"version\": VERSION,\n        \"port\": PORT,\n        \"print_mode\": PRINT_MODE,\n        \"config\": config_printers,\n        \"installed_printers\": installed,\n        \"mapped_printers\": mapped,\n    })\n\n@app.route(\"/printers\", methods=[\"GET\"])\ndef list_printers():\n    global PRINTER_MAP\n    config_printers = load_printer_config()\n    PRINTER_MAP = config_printers[\"PRINTER_MAP\"]\n\n    installed = get_installed_printers()\n    default = win32print.GetDefaultPrinter()\n    return jsonify({\"printers\": installed, \"default\": default, \"mapped\": PRINTER_MAP})\n\n@app.route(\"/print\", methods=[\"POST\"])\ndef print_ticket():\n    data = request.get_json(silent=True)\n    if not data:\n        return jsonify({\"success\": False, \"error\": \"No data received\"}), 400\n        \n    printer_key  = data.get(\"printer\", \"cuentas\")\n    raw_data_url = data.get(\"raw_data\", \"\")\n    raw_bytes    = urllib.parse.unquote_to_bytes(raw_data_url)\n    \n    if check_duplicate_and_register(raw_bytes):\n        log.info(f\"\u26a0\ufe0f Ticket duplicado detectado v\u00eda API POST /print. Omitiendo impresi\u00f3n f\u00edsica.\")\n        return jsonify({\"success\": True, \"ignored\": True, \"reason\": \"duplicate\", \"bytes_sent\": 0})\n        \n    try:\n        printer_name = resolve_printer_name(printer_key)\n        print_data(printer_name, raw_bytes, ticket_type=printer_key)\n        return jsonify({\"success\": True, \"printer_used\": printer_name, \"bytes_sent\": len(raw_bytes)})\n    except Exception as e:\n        log.error(f\"\u274c Error en API /print: {e}\")\n        return jsonify({\"success\": False, \"error\": str(e)}), 500\n\n@app.route(\"/test-print\", methods=[\"POST\"])\ndef test_print():\n    try:\n        data         = request.get_json(silent=True) or {}\n        printer_key  = data.get(\"printer\", \"cuentas\")\n        printer_name = resolve_printer_name(printer_key)\n\n        ESC = b\"\\x1b\"\n        GS  = b\"\\x1d\"\n        now = datetime.now().strftime(\"%d/%m/%Y %H:%M:%S\")\n\n        test_bytes = (\n            ESC + b\"@\"\n            + ESC + b\"a\\x01\"\n            + ESC + b\"!\\x18\"\n            + \"\ud83c\udf2e TACOS ROY AZUCENAS \ud83c\udf2e\\n\".encode(\"utf-8\")\n            + ESC + b\"!\\x00\"\n            + \"=== TICKET PRO GDI VECTORIAL ===\\n\\n\".encode(\"utf-8\")\n            + ESC + b\"a\\x00\"\n            + f\"Impresora : {printer_name}\\n\".encode(\"utf-8\")\n            + f\"Sentinel  : v{VERSION} (Puerto {PORT})\\n\".encode(\"utf-8\")\n            + f\"Fecha     : {now}\\n\".encode(\"utf-8\")\n            + \"Atendio   : BLADIMIR (ADMIN) \ud83d\udc64\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + \"2 x \ud83c\udf2e TACOS AL PASTOR      $100.00\\n\".encode(\"utf-8\")\n            + \"  * Con todo y salsa verde\\n\".encode(\"utf-8\")\n            + \"1 x \ud83c\udf7a CERVEZA ARTESANAL    $80.00\\n\".encode(\"utf-8\")\n            + \"1 x \ud83c\udf79 MARGARITA AZUL       $95.50\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + \"SUBTOTAL: $275.50\\n\".encode(\"utf-8\")\n            + \"PROPINA (10%): $27.55\\n\".encode(\"utf-8\")\n            + \"TOTAL: $303.05\\n\".encode(\"utf-8\")\n            + \"----------------------------------------\\n\".encode(\"utf-8\")\n            + ESC + b\"a\\x01\"\n            + \"\u00a1Gracias por su preferencia! \u2b50\\n\".encode(\"utf-8\")\n            + \"Facturacion: www.cocinet.app \ud83c\udf10\\n\".encode(\"utf-8\")\n            + \"\\n\\n\\n\"\n            + GS + b\"V\\x41\\x03\"\n        )\n\n        print_data(printer_name, test_bytes, ticket_type=printer_key)\n        log.info(f\"[TEST] Pagina de prueba impresa en '{printer_name}'\")\n        return jsonify({\"success\": True, \"printer_used\": printer_name})\n    except Exception as e:\n        log.error(f\"test-print error: {e}\")\n        return jsonify({\"error\": str(e)}), 500\n\n@app.route(\"/diag-print\", methods=[\"POST\"])\ndef diag_print():\n    logs = []\n    def add_log(msg):\n        timestamp = datetime.now().strftime('%H:%M:%S')\n        full_msg = f\"{timestamp} - {msg}\"\n        logs.append(full_msg)\n        log.info(f\"[DIAG] {msg}\")\n\n    try:\n        data = request.get_json(silent=True) or {}\n        printer_key = data.get(\"printer\", \"cuentas\")\n        add_log(f\"Iniciando diagn\u00f3stico para impresora clave: {printer_key}\")\n\n        printer_name = resolve_printer_name(printer_key)\n        add_log(f\"Impresora resuelta: {printer_name}\")\n\n        ESC = b\"\\x1b\"\n        GS  = b\"\\x1d\"\n        test_bytes = ESC + b\"@\" + b\"Diagnostico OK\\n\" + GS + b\"V\\x41\\x03\"\n\n        add_log(\"Intentando imprimir p\u00e1gina de prueba de diagn\u00f3stico...\")\n        print_data(printer_name, test_bytes, ticket_type=printer_key)\n        add_log(\"Impresi\u00f3n de diagn\u00f3stico completada.\")\n\n        return jsonify({\"success\": True, \"logs\": logs})\n    except Exception as e:\n        err_msg = f\"Error durante diagn\u00f3stico: {str(e)}\"\n        add_log(err_msg)\n        return jsonify({\"success\": False, \"logs\": logs, \"error\": str(e)}), 500\n\n# \u2500\u2500\u2500 Deduplicaci\u00f3n por Hash \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef generar_hash(raw_bytes: bytes) -> str:\n    return hashlib.md5(raw_bytes).hexdigest()\n\ndef check_duplicate_and_register(raw_bytes: bytes, job_id: str = None) -> bool:\n    ticket_hash = generar_hash(raw_bytes)\n    db_path = os.path.join(BASE_DIR, \"restaurant.db\")\n    \n    try:\n        conn = sqlite3.connect(db_path, timeout=30)\n        cursor = conn.cursor()\n        \n        cursor.execute(\"\"\"\n            CREATE TABLE IF NOT EXISTS print_queue (\n                id TEXT PRIMARY KEY,\n                printer_key TEXT NOT NULL,\n                raw_data TEXT NOT NULL,\n                status TEXT NOT NULL DEFAULT 'pending',\n                hash TEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                printed_at TIMESTAMP\n            )\n        \"\"\")\n        conn.commit()\n        \n        cursor.execute(\"\"\"\n            SELECT id FROM print_queue \n            WHERE hash=? AND status='printed' AND printed_at > datetime('now', '-10 seconds')\n        \"\"\", (ticket_hash,))\n        \n        row = cursor.fetchone()\n        if row:\n            if job_id:\n                cursor.execute(\"\"\"\n                    UPDATE print_queue \n                    SET status='duplicate', updated_at=CURRENT_TIMESTAMP \n                    WHERE id=?\n                \"\"\", (job_id,))\n                conn.commit()\n            conn.close()\n            return True\n            \n        if not job_id:\n            new_id = f\"http-{int(time.time() * 1000)}-{ticket_hash[:8]}\"\n            raw_data_encoded = urllib.parse.quote_from_bytes(raw_bytes)\n            cursor.execute(\"\"\"\n                INSERT INTO print_queue (id, printer_key, raw_data, status, hash, printed_at)\n                VALUES (?, 'http_api', ?, 'printed', ?, CURRENT_TIMESTAMP)\n            \"\"\", (new_id, raw_data_encoded, ticket_hash))\n            conn.commit()\n            \n        conn.close()\n        return False\n    except Exception as e:\n        log.error(f\"Error en validaci\u00f3n de deduplicaci\u00f3n: {e}\")\n        return False\n\n# \u2500\u2500\u2500 Polling DB \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\ndef db_polling_loop():\n    db_path = os.path.join(BASE_DIR, \"restaurant.db\")\n    log.info(f\"\ud83d\udd0c Iniciando polling de base de datos en: {db_path}\")\n    while True:\n        try:\n            conn = sqlite3.connect(db_path, timeout=30)\n            cursor = conn.cursor()\n            cursor.execute(\"\"\"\n                CREATE TABLE IF NOT EXISTS print_queue (\n                    id TEXT PRIMARY KEY,\n                    printer_key TEXT NOT NULL,\n                    raw_data TEXT NOT NULL,\n                    status TEXT NOT NULL DEFAULT 'pending',\n                    hash TEXT,\n                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                    printed_at TIMESTAMP\n                )\n            \"\"\")\n            conn.commit()\n            conn.close()\n            \n            conn = sqlite3.connect(db_path, timeout=30)\n            conn.execute(\"BEGIN IMMEDIATE\")\n            cursor = conn.cursor()\n            cursor.execute(\"SELECT id, printer_key, raw_data FROM print_queue WHERE status='pending'\")\n            jobs = cursor.fetchall()\n            \n            if jobs:\n                for job_id, _, _ in jobs:\n                    cursor.execute(\"UPDATE print_queue SET status='processing', updated_at=CURRENT_TIMESTAMP WHERE id=?\", (job_id,))\n                conn.commit()\n            else:\n                conn.commit()\n            conn.close()\n            \n            for job_id, printer_key, raw_data in jobs:\n                try:\n                    raw_bytes = urllib.parse.unquote_to_bytes(raw_data)\n                    ticket_hash = generar_hash(raw_bytes)\n                    \n                    if check_duplicate_and_register(raw_bytes, job_id):\n                        log.info(f\"\u26a0\ufe0f Ticket duplicado detectado en cola, no se imprime (ID: {job_id})\")\n                        continue\n                    \n                    printer_name = resolve_printer_name(printer_key)\n                    print_data(printer_name, raw_bytes, ticket_type=printer_key)\n                    \n                    conn2 = sqlite3.connect(db_path, timeout=30)\n                    cursor2 = conn2.cursor()\n                    cursor2.execute(\"\"\"\n                        UPDATE print_queue\n                        SET status='printed', updated_at=CURRENT_TIMESTAMP, printed_at=CURRENT_TIMESTAMP, hash=?\n                        WHERE id=?\n                    \"\"\", (ticket_hash, job_id))\n                    conn2.commit()\n                    conn2.close()\n                    log.info(f\"\u2705 Ticket impreso con \u00e9xito (ID: {job_id}, Impresora: {printer_name})\")\n                    \n                except Exception as ex:\n                    log.error(f\"\u274c Error al procesar trabajo de impresi\u00f3n {job_id}: {ex}\")\n                    conn2 = sqlite3.connect(db_path, timeout=30)\n                    cursor2 = conn2.cursor()\n                    cursor2.execute(\"UPDATE print_queue SET status='failed', updated_at=CURRENT_TIMESTAMP WHERE id=?\", (job_id,))\n                    conn2.commit()\n                    conn2.close()\n            \n            time.sleep(2)\n        except Exception as e:\n            log.error(f\"\u274c Error en bucle de polling: {e}\")\n            time.sleep(5)\n\n# \u2500\u2500\u2500 Servicio Windows \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\nclass CocinetPrinterService(win32serviceutil.ServiceFramework):\n    _svc_name_ = \"CocinetPrinterSentinel\"\n    _svc_display_name_ = \"COCINET PRO - Print Sentinel\"\n    _svc_description_ = \"Servidor local HTTP de impresi\u00f3n ESC/POS para COCINET PRO.\"\n\n    def __init__(self, args):\n        win32serviceutil.ServiceFramework.__init__(self, args)\n        self.stop_event = win32event.CreateEvent(None, 0, 0, None)\n\n    def SvcStop(self):\n        log.info(\"Servicio detenido por Windows SCM.\")\n        self.ReportServiceStatus(win32service.SERVICE_STOP_PENDING)\n        stop_flask()\n        win32event.SetEvent(self.stop_event)\n\n    def SvcDoRun(self):\n        servicemanager.LogMsg(\n            servicemanager.EVENTLOG_INFORMATION_TYPE,\n            servicemanager.PYS_SERVICE_STARTED,\n            (self._svc_name_, \"\"),\n        )\n        log.info(\"Servicio iniciado por Windows SCM.\")\n        flask_thread = threading.Thread(target=run_flask, daemon=True)\n        flask_thread.start()\n        win32event.WaitForSingleObject(self.stop_event, win32event.INFINITE)\n\ndef run_flask():\n    db_thread = threading.Thread(target=db_polling_loop, daemon=True)\n    db_thread.start()\n    from werkzeug.serving import make_server\n    global _flask_server\n    _flask_server = make_server(\"0.0.0.0\", PORT, app)\n    log.info(f\"COCINET Print Sentinel v{VERSION} escuchando en puerto {PORT}\")\n    _flask_server.serve_forever()\n\ndef stop_flask():\n    global _flask_server\n    try:\n        _flask_server.shutdown()\n    except Exception:\n        pass\n\ndef run_console():\n    print()\n    print(\"============================================================\")\n    print(\"   COCINET PRO - Windows Print Sentinel  v3.4\")\n    print(\"============================================================\")\n    print(f\"   URL:  http://localhost:{PORT}\")\n    print(f\"   Modo: GDI Vectorial (Arial / Segoe UI)\")\n    print(\"------------------------------------------------------------\")\n    try:\n        installed = get_installed_printers()\n        print(f\"  Impresoras detectadas ({len(installed)}):\")\n        for p in installed:\n            found = any(v.upper() == p.upper() for v in PRINTER_MAP.values())\n            tag   = \"[MAPEADA]   \" if found else \"[disponible]\"\n            print(f\"    {tag}  {p}\")\n    except Exception as e:\n        print(f\"  [WARN] No se pudo listar impresoras: {e}\")\n    print()\n    print(\"  Presiona Ctrl+C para detener.\\n\")\n    try:\n        run_flask()\n    except KeyboardInterrupt:\n        print(\"\\n  Servidor detenido.\")\n\nif __name__ == \"__main__\":\n    if len(sys.argv) == 1:\n        run_console()\n    else:\n        win32serviceutil.HandleCommandLine(CocinetPrinterService)\n",
  "instalador.bat": "@echo off\nchcp 65001 > nul\nsetlocal enabledelayedexpansion\ntitle INSTALADOR SENTINELA COCINET PRO\n\n:: Verificar si el script ya se esta ejecutando como Administrador\nnet session >nul 2>&1\nif !errorlevel! neq 0 (\n    echo.\n    echo [INFO] Solicitando elevacion de privilegios de Administrador...\n    echo [INFO] Por favor presiona 'Si' en el dialogo de Windows que aparecera a continuacion.\n    echo.\n    powershell -Command \"Start-Process -FilePath '%~f0' -Verb RunAs\"\n    exit /b\n)\n\ncd /d \"%~dp0\"\n\necho =======================================================================\necho   [+] COCINET PRO - INICIANDO INSTALADOR DEL SENTINELA DE IMPRESION\necho =======================================================================\necho.\necho [INFO] Detectando instalacion de Python compatible (v3.11 / v3.12)...\n\nset \"PYTHON_CMD=\"\n\n:: 1. Priorizar Python 3.11 o 3.12 mediante el lanzador oficial 'py'\npy -3.11 --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=py -3.11\"\n    goto :PYTHON_FOUND\n)\n\npy -3.12 --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=py -3.12\"\n    goto :PYTHON_FOUND\n)\n\n:: 2. Buscar ejecutable directo de Python 3.11 o 3.12 en el sistema\nif exist \"C:\\Users\\DELL\\AppData\\Local\\Programs\\Python\\Python311\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Users\\DELL\\AppData\\Local\\Programs\\Python\\Python311\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"C:\\Users\\CAJA\\AppData\\Local\\Programs\\Python\\Python311\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Users\\CAJA\\AppData\\Local\\Programs\\Python\\Python311\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"%LOCALAPPDATA%\\Programs\\Python\\Python311\\python.exe\" (\n    set \"PYTHON_CMD=\"%LOCALAPPDATA%\\Programs\\Python\\Python311\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"C:\\Program Files\\Python311\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Program Files\\Python311\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"C:\\Users\\DELL\\AppData\\Local\\Programs\\Python\\Python312\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Users\\DELL\\AppData\\Local\\Programs\\Python\\Python312\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"%LOCALAPPDATA%\\Programs\\Python\\Python312\\python.exe\" (\n    set \"PYTHON_CMD=\"%LOCALAPPDATA%\\Programs\\Python\\Python312\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\nif exist \"C:\\Program Files\\Python312\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Program Files\\Python312\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\n\n:: 3. Probar lanzador generico 'py -3' o 'python'\npy -3 --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=py -3\"\n    goto :PYTHON_FOUND\n)\n\npython --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=python\"\n    goto :PYTHON_FOUND\n)\n\n:PYTHON_NOT_FOUND\necho.\necho [AVISO] No se detecto Python 3.11 / 3.12 instalado en el sistema.\necho [INFO] Descargando e instalando Python 3.11.9 de forma automatica...\necho.\n\nset \"INSTALLER_PATH=%TEMP%\\python_installer_setup.exe\"\n\ncurl -L \"https://www.python.org/ftp/python/3.11.9/python-3.11.9-amd64.exe\" -o \"!INSTALLER_PATH!\"\nif not exist \"!INSTALLER_PATH!\" (\n    powershell -Command \"[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12; (New-Object System.Net.WebClient).DownloadFile('https://www.python.org/ftp/python/3.11.9/python-3.11.9-amd64.exe', '!INSTALLER_PATH!')\"\n)\n\nif not exist \"!INSTALLER_PATH!\" (\n    echo [ERROR] No se pudo descargar el instalador de Python automaticamente.\n    echo [INFO] Revisa tu conexion a Internet o descarga Python 3.11 manualmente de https://www.python.org/downloads/\n    pause\n    exit /b 1\n)\n\necho.\necho [INFO] Instalando Python 3.11 de forma silenciosa para todos los usuarios...\n\"!INSTALLER_PATH!\" /quiet InstallAllUsers=1 PrependPath=1 Include_test=0\n\nif exist \"!INSTALLER_PATH!\" del /f /q \"!INSTALLER_PATH!\" >nul 2>&1\n\npy -3.11 --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=py -3.11\"\n    goto :PYTHON_FOUND\n)\n\nif exist \"C:\\Program Files\\Python311\\python.exe\" (\n    set \"PYTHON_CMD=\"C:\\Program Files\\Python311\\python.exe\"\"\n    goto :PYTHON_FOUND\n)\n\npython --version >nul 2>&1\nif !errorlevel! equ 0 (\n    set \"PYTHON_CMD=python\"\n    goto :PYTHON_FOUND\n)\n\necho [ERROR] La instalacion automatica de Python no finalizo correctamente.\npause\nexit /b 1\n\n:PYTHON_FOUND\necho [OK] Python compatible detectado correctamente: !PYTHON_CMD!\necho [INFO] Ejecutando proceso de instalacion del servicio del Sentinela...\n!PYTHON_CMD! \"%~dp0instalador_sentinela.py\"\nif !errorlevel! neq 0 (\n    echo.\n    echo [ERROR] Hubo un problema durante el proceso de instalacion.\n    echo.\n    pause\n    exit /b !errorlevel!\n)\necho.\necho =======================================================================\necho   [OK] INSTALACION FINALIZADA CON EXITO! PUEDES CERRAR ESTA VENTANA\necho =======================================================================\npause\n",
  "instalador_sentinela.py": "# -*- coding: utf-8 -*-\n\"\"\"\n================================================================================\n   \ud83d\ude80 COCINET PRO - Instalador y Actualizador del Sentinela de Windows v3.1 \ud83d\ude80\n================================================================================\nEste script detiene, desinstala, actualiza dependencias y reinstala de forma\nlimpia el servicio de Windows del Sentinela de Impresi\u00f3n COCINET PRO.\n\nRequisitos:\n  - Ejecutar en Windows con Python 3 instalado.\n  - Se auto-elevar\u00e1 a permisos de Administrador autom\u00e1ticamente si es necesario.\n================================================================================\n\"\"\"\n\nimport os\nimport sys\nimport time\nimport subprocess\nimport urllib.request\nimport json\n\n# Asegurar codificaci\u00f3n UTF-8 en consola de Windows para evitar errores con Emojis\nif hasattr(sys.stdout, 'reconfigure'):\n    try:\n        sys.stdout.reconfigure(encoding='utf-8', errors='replace')\n        sys.stderr.reconfigure(encoding='utf-8', errors='replace')\n    except Exception:\n        pass\n\n# Nombre exacto del servicio de Windows\nSERVICE_NAME = \"CocinetPrinterSentinel\"\nSENTINEL_SCRIPT = \"sentinel_printer.py\"\nPORT = 3010\n\ndef is_admin():\n    \"\"\"Verifica si el script tiene privilegios de Administrador.\"\"\"\n    try:\n        import ctypes\n        return ctypes.windll.shell32.IsUserAnAdmin() != 0\n    except Exception:\n        return False\n\ndef elevate_privileges():\n    \"\"\"Intenta re-ejecutar el script actual con permisos de Administrador manteniendo la consola visible.\"\"\"\n    import ctypes\n    # Si ya es admin, no hacemos nada\n    if is_admin():\n        return True\n    \n    print(\"\ud83d\udd11 [INFO] Solicitando elevaci\u00f3n de privilegios de Administrador... Por favor acepta el di\u00e1logo de Windows.\")\n    try:\n        script = os.path.abspath(sys.argv[0])\n        script_dir = os.path.dirname(script)\n        params = \" \".join(sys.argv[1:])\n        cmd_args = f'/k cd /d \"{script_dir}\" && \"{sys.executable}\" \"{script}\" {params}'\n        result = ctypes.windll.shell32.ShellExecuteW(None, \"runas\", \"cmd.exe\", cmd_args, script_dir, 1)\n        if int(result) > 32:\n            print(\"\ud83d\ude80 [OK] Re-lanzando proceso con permisos de administrador en nueva consola...\")\n            sys.exit(0)\n        else:\n            print(\"\u274c [ERROR] No se concedieron los permisos de Administrador necesarios.\")\n            return False\n    except Exception as e:\n        print(f\"\u274c [ERROR] Error al intentar elevar privilegios: {e}\")\n        return False\n\ndef print_banner():\n    print(\"\\n\" + \"=\"*80)\n    print(\"   \ud83c\udf1f COCINET PRO - ACTUALIZADOR DE SERVICIO DE WINDOWS PARA EL SENTINELA \ud83c\udf1f\")\n    print(\"=\"*80 + \"\\n\")\n\ndef run_command(args, step_name, ignore_error=False):\n    \"\"\"Ejecuta un comando del sistema informando detalladamente con emojis.\"\"\"\n    print(f\"\u23f3 [PROCESANDO] Paso: {step_name}...\")\n    try:\n        # Usamos shell=True para comandos internos o scripts\n        result = subprocess.run(\n            args, \n            stdout=subprocess.PIPE, \n            stderr=subprocess.PIPE, \n            text=True, \n            timeout=30,\n            shell=True\n        )\n        if result.returncode == 0:\n            print(f\"\u2705 [\u00c9XITO] Paso '{step_name}' completado correctamente.\")\n            return True\n        else:\n            if ignore_error:\n                print(f\"\u26a0\ufe0f [AVISO] Paso '{step_name}' finaliz\u00f3 con c\u00f3digo {result.returncode} (Ignorado).\")\n                return True\n            print(f\"\u274c [ERROR] Fall\u00f3 el paso: {step_name}\")\n            print(f\"   Detalles del sistema: {result.stderr.strip() or result.stdout.strip()}\")\n            return False\n    except subprocess.TimeoutExpired:\n        print(f\"\u23f0 [TIMEOUT] Se agot\u00f3 el tiempo de espera (30s) para: {step_name}\")\n        return False\n    except Exception as e:\n        print(f\"\ud83d\udca5 [CR\u00cdTICO] Excepci\u00f3n en '{step_name}': {e}\")\n        return False\n\ndef check_sentinel_file():\n    \"\"\"Verifica que el archivo del sentinela exista en la misma carpeta.\"\"\"\n    current_dir = os.path.dirname(os.path.abspath(__file__))\n    target_path = os.path.join(current_dir, SENTINEL_SCRIPT)\n    if os.path.exists(target_path):\n        return target_path\n    \n    # Buscar en el directorio actual de ejecuci\u00f3n\n    if os.path.exists(SENTINEL_SCRIPT):\n        return os.path.abspath(SENTINEL_SCRIPT)\n        \n    return None\n\ndef verify_service_status():\n    \"\"\"Realiza una petici\u00f3n HTTP al puerto del Sentinela para verificar que est\u00e9 activo.\"\"\"\n    print(f\"\ud83d\udd0d [VERIFICACI\u00d3N] Conectando con el Sentinela en http://localhost:{PORT}/status ...\")\n    time.sleep(2) # Esperar a que el servicio se asiente\n    try:\n        url = f\"http://localhost:{PORT}/status\"\n        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})\n        with urllib.request.urlopen(req, timeout=3) as response:\n            if response.status == 200:\n                data = json.loads(response.read().decode('utf-8'))\n                print(\"\\n\ud83c\udf89 \u00a1EL SENTINELA SE ENCUENTRA EN L\u00cdNEA Y OPERANDO CON \u00c9XITO! \ud83c\udf89\")\n                print(f\"   \ud83d\udce1 Estado: {data.get('status', 'desconocido').upper()}\")\n                print(f\"   \ud83d\udee0\ufe0f  Servicio: {data.get('service', 'N/A')}\")\n                print(f\"   \ud83c\udff7\ufe0f  Versi\u00f3n Instalada: v{data.get('version', '6.0.0')}\")\n                print(f\"   \ud83d\udd0c Puerto: {data.get('port', PORT)}\")\n                print(f\"   \ud83d\udccb Impresoras Mapeadas: {list(data.get('mapped_printers', {}).keys())}\")\n                print(\"   \u2728 Novedades v6.0.0:\")\n                print(\"      \u2022 Desconcatenaci\u00f3n autom\u00e1tica de productos pegados en el mismo rengl\u00f3n.\")\n                print(\"      \u2022 Despliegue estricto de 1 l\u00ednea por producto con montos y suma exactos.\")\n                print(\"================================================================================\")\n                print(\"\ud83d\udca1 \u00a1Listo! El Sentinela de Windows ya est\u00e1 actualizado e impresoras listas.\")\n                print(\"================================================================================\\n\")\n                return True\n    except Exception as e:\n        print(f\"\u26a0\ufe0f [AVISO] No se pudo obtener respuesta HTTP directa del Sentinela ({e}).\")\n        print(\"   Sin embargo, el servicio de Windows se ha configurado e iniciado en segundo plano.\")\n        print(\"   Puedes revisar los logs detallados en 'sentinel_printer.log' para confirmar su operaci\u00f3n.\")\n        return False\n\ndef configure_printer_sizes(target_dir):\n    \"\"\"Pregunta al usuario por consola interactiva los nombres, anchos de papel, logotipo y fuentes de las impresoras.\"\"\"\n    config_file = os.path.join(target_dir, \"printer_config.json\")\n    \n    # Valores base por defecto\n    current_config = {\n        \"PRINTER_MAP\": {\n            \"cuentas\": \"CUENTAS\",\n            \"cocina\":  \"COCINA\",\n            \"barra\":   \"BARRA\",\n        },\n        \"PRINTER_PAPER_SIZES\": {\n            \"cuentas\": \"80mm\",\n            \"cocina\":  \"80mm\",\n            \"barra\":   \"80mm\",\n        },\n        \"LOGO_PATH\": \"C:\\\\buzon\\\\logo.jpg\",\n        \"FONT_NAME\": \"Arial\",\n        \"FONT_SIZE_PT\": 16.0\n    }\n    \n    # Leer el existente si existe para conservar la config anterior del usuario\n    if os.path.exists(config_file):\n        try:\n            with open(config_file, \"r\", encoding=\"utf-8\") as f:\n                data = json.load(f)\n                if \"PRINTER_MAP\" in data:\n                    current_config[\"PRINTER_MAP\"].update(data[\"PRINTER_MAP\"])\n                if \"PRINTER_PAPER_SIZES\" in data:\n                    current_config[\"PRINTER_PAPER_SIZES\"].update(data[\"PRINTER_PAPER_SIZES\"])\n                if \"LOGO_PATH\" in data:\n                    current_config[\"LOGO_PATH\"] = data[\"LOGO_PATH\"]\n                if \"FONT_NAME\" in data:\n                    current_config[\"FONT_NAME\"] = data[\"FONT_NAME\"]\n                if \"FONT_SIZE_PT\" in data:\n                    current_config[\"FONT_SIZE_PT\"] = float(data[\"FONT_SIZE_PT\"])\n        except Exception:\n            pass\n            \n    print(\"\\n\" + \"=\"*80)\n    print(\"    \u2699\ufe0f  CONFIGURACI\u00d3N DE IMPRESORAS, ANCHOS DE PAPEL Y LOGOTIPO \u2699\ufe0f\")\n    print(\"=\"*80)\n    \n    # Listar impresoras instaladas en Windows\n    installed_list = []\n    try:\n        import win32print\n        flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS\n        installed_list = [p[2] for p in win32print.EnumPrinters(flags)]\n        if installed_list:\n            print(\"\ud83d\udda8\ufe0f  Impresoras detectadas en este equipo:\")\n            for p in installed_list:\n                print(f\"   \u2022 {p}\")\n            print(\"\")\n    except Exception:\n        pass\n\n    print(\"Por favor, ingresa los datos correspondientes.\\n\")\n    \n    # Preguntar ruta del logotipo\n    default_logo = current_config.get(\"LOGO_PATH\", \"C:\\\\buzon\\\\logo.jpg\")\n    logo_input = input(f\"\u27a4 Ruta f\u00edsica del logotipo (.jpg) (Enter para '{default_logo}'): \").strip()\n    new_logo = logo_input if logo_input else default_logo\n    print(f\"   \u21b3 Logotipo configurado en: '{new_logo}'\\n\")\n    \n    # Preguntar tipograf\u00eda y tama\u00f1o\n    default_font = current_config.get(\"FONT_NAME\", \"Arial\")\n    font_input = input(f\"\u27a4 Nombre de la tipograf\u00eda (Enter para '{default_font}'): \").strip()\n    new_font = font_input if font_input else default_font\n    \n    default_size = current_config.get(\"FONT_SIZE_PT\", 16.0)\n    size_input = input(f\"\u27a4 Tama\u00f1o de letra base en puntos (Enter para '{default_size}'): \").strip()\n    try:\n        new_size = float(size_input) if size_input else default_size\n    except Exception:\n        new_size = default_size\n        \n    print(f\"   \u21b3 Tipograf\u00eda configurada: '{new_font}' con tama\u00f1o {new_size} pt.\\n\")\n    \n    new_map = {}\n    new_sizes = {}\n    \n    for area in [\"cuentas\", \"cocina\", \"barra\"]:\n        default_name = current_config[\"PRINTER_MAP\"].get(area, \"CUENTAS\")\n        # Si la predeterminada no coincide con ninguna instalada, sugerir la primera disponible de Windows\n        if installed_list and not any(p.upper() == default_name.upper() for p in installed_list):\n            default_name = installed_list[0]\n\n        name = input(f\"\u27a4 Nombre de impresora en Windows para '{area}' (Enter para '{default_name}'): \").strip()\n        new_map[area] = name if name else default_name\n        \n        default_size = current_config[\"PRINTER_PAPER_SIZES\"][area]\n        size_in = input(f\"   \u00bfAncho de papel de esta impresora? (Enter para '{default_size}', o ingresa '58' o '80'): \").strip()\n        if size_in == \"58\":\n            new_sizes[area] = \"58mm\"\n        elif size_in == \"80\":\n            new_sizes[area] = \"80mm\"\n        else:\n            new_sizes[area] = default_size\n            \n        print(f\"   \u21b3 Guardado: Impresora '{new_map[area]}' con papel {new_sizes[area]}.\\n\")\n        \n    config_payload = {\n        \"PRINTER_MAP\": new_map,\n        \"PRINTER_PAPER_SIZES\": new_sizes,\n        \"LOGO_PATH\": new_logo,\n        \"FONT_NAME\": new_font,\n        \"FONT_SIZE_PT\": new_size\n    }\n    \n    try:\n        with open(config_file, \"w\", encoding=\"utf-8\") as f:\n            json.dump(config_payload, f, indent=4, ensure_ascii=False)\n        print(f\"\u2705 [OK] Configuraci\u00f3n guardada en: {config_file}\\n\")\n    except Exception as e:\n        print(f\"\u26a0\ufe0f [AVISO] No se pudo escribir el archivo de configuraci\u00f3n ({e}).\")\n\ndef main():\n    print_banner()\n\n    # 1. Asegurar elevaci\u00f3n de privilegios de Administrador\n    if not is_admin():\n        if not elevate_privileges():\n            print(\"\ud83d\uded1 [PASO 1 FALLADO] El script REQUIERE ejecutarse con permisos de Administrador para instalar servicios.\")\n            print(\"\ud83d\udca1 Sugerencia: Haz clic derecho sobre el instalador y selecciona 'Ejecutar como Administrador'.\")\n            input(\"\\nPresiona Enter para salir...\")\n            sys.exit(1)\n        sys.exit(0)\n    else:\n        print(\"\ud83d\udd13 [PASO 1 OK] Permisos de Administrador detectados y validados.\")\n\n    # 2. Localizar archivo sentinel_printer.py\n    sentinel_path = check_sentinel_file()\n    if not sentinel_path:\n        print(f\"\ud83d\uded1 [PASO 2 FALLADO] No se encontr\u00f3 el archivo '{SENTINEL_SCRIPT}' en la carpeta actual.\")\n        print(\"\ud83d\udca1 Sugerencia: Aseg\u00farate de extraer este instalador en el mismo directorio donde est\u00e1 el sentinela.\")\n        input(\"\\nPresiona Enter para salir...\")\n        sys.exit(1)\n    else:\n        print(f\"\ud83d\udcc2 [PASO 2 OK] Archivo del Sentinela localizado en: {sentinel_path}\")\n\n    # Cambiar al directorio del script para evitar fallos de rutas relativas\n    os.chdir(os.path.dirname(sentinel_path))\n\n    # 3. Detener y cerrar forzadamente cualquier servicio o proceso previo del Sentinela\n    print(\"\ud83d\uded1 [PROCESANDO] Deteniendo y liberando memoria del Sentinela previo...\")\n    run_command(f'\"{sys.executable}\" \"{SENTINEL_SCRIPT}\" stop', \"Detener servicio mediante script\", ignore_error=True)\n    run_command(f'sc stop {SERVICE_NAME}', \"Detener servicio mediante SCM de Windows\", ignore_error=True)\n    run_command('taskkill /F /FI \"SERVICES eq COCINETPrintSentinel\"', \"Cierre forzado por SCM\", ignore_error=True)\n    run_command('taskkill /F /IM pythonservice.exe', \"Cierre forzado de pythonservice.exe\", ignore_error=True)\n    time.sleep(2.0)\n\n    # 4. Desinstalar servicio existente\n    print(\"\ud83d\uddd1\ufe0f [PROCESANDO] Limpiando registro del servicio previo de Windows...\")\n    run_command(f'\"{sys.executable}\" \"{SENTINEL_SCRIPT}\" remove', \"Eliminar servicio mediante script\", ignore_error=True)\n    run_command(f'sc delete {SERVICE_NAME}', \"Eliminar servicio mediante SCM de Windows\", ignore_error=True)\n    time.sleep(1.5)\n\n    # 5. Instalar/Actualizar Dependencias del Sistema\n    print(\"\ud83d\udce6 [PROCESANDO] Instalando y actualizando librer\u00edas de Python requeridas...\")\n    deps = [\"pywin32\", \"Flask\", \"flask-cors\"]\n    for dep in deps:\n        if not run_command(f'\"{sys.executable}\" -m pip install --upgrade {dep}', f\"Instalar/Actualizar paquete '{dep}'\"):\n            print(f\"\ud83d\uded1 [PASO 5 FALLADO] No se pudo instalar la dependencia cr\u00edtica: {dep}\")\n            print(\"\ud83d\udca1 Sugerencia: Revisa tu conexi\u00f3n a Internet y aseg\u00farate de que 'pip' est\u00e9 en tu PATH.\")\n            input(\"\\nPresiona Enter para salir...\")\n            sys.exit(1)\n    \n    # 6. Ejecutar script de post-instalaci\u00f3n de pywin32 para registrar DLLs en System32\n    print(\"\u2699\ufe0f [PROCESANDO] Registrando variables del sistema para servicios de Python en Windows...\")\n    try:\n        import shutil\n        sys32_path = os.environ.get(\"SystemRoot\", r\"C:\\Windows\") + r\"\\System32\"\n        pywin32_sys32 = os.path.join(sys.prefix, \"Lib\", \"site-packages\", \"pywin32_system32\")\n        if os.path.exists(pywin32_sys32):\n            for f in os.listdir(pywin32_sys32):\n                if f.lower().endswith(\".dll\"):\n                    src = os.path.join(pywin32_sys32, f)\n                    try:\n                        shutil.copy2(src, os.path.join(sys32_path, f))\n                        shutil.copy2(src, os.path.join(sys.prefix, f))\n                    except Exception:\n                        pass\n    except Exception:\n        pass\n\n    post_install_cmd = f'\"{sys.executable}\" -c \"import os, sys; print(os.path.join(sys.prefix, \\'Scripts\\', \\'pywin32_postinstall.py\\'))\"'\n    try:\n        post_path = subprocess.check_output(post_install_cmd, shell=True, text=True).strip()\n        if os.path.exists(post_path):\n            run_command(f'\"{sys.executable}\" \"{post_path}\" -install', \"Ejecutar post-instalaci\u00f3n de pywin32\", ignore_error=True)\n        else:\n            # Buscar en el entorno virtual si aplica\n            alt_path = os.path.join(sys.prefix, \"Scripts\", \"pywin32_postinstall.py\")\n            if os.path.exists(alt_path):\n                run_command(f'\"{sys.executable}\" \"{alt_path}\" -install', \"Ejecutar post-instalaci\u00f3n de pywin32 alternativo\", ignore_error=True)\n    except Exception as e:\n        print(f\"\u26a0\ufe0f [AVISO] No se pudo registrar pywin32_postinstall de forma automatizada ({e}). Continuando de todos modos...\")\n\n    # 6.5. Configuraci\u00f3n de Impresoras y Tama\u00f1os de Papel (58mm / 80mm)\n    configure_printer_sizes(os.path.dirname(sentinel_path))\n\n    # 7. Instalar el nuevo servicio de Windows\n    print(\"\ud83d\udd0c [PROCESANDO] Instalando el renovado servicio de Windows del Sentinela v3.6.0...\")\n    # Instalamos con inicio retrasado o autom\u00e1tico para que el spooler de Windows est\u00e9 listo al iniciar\n    if not run_command(f'\"{sys.executable}\" \"{SENTINEL_SCRIPT}\" install', \"Registrar Servicio de Windows\"):\n        print(\"\ud83d\uded1 [PASO 7 FALLADO] Error al registrar el servicio de Windows.\")\n        print(\"\ud83d\udca1 Sugerencia: Aseg\u00farate de que no haya procesos de Python fantasma bloqueando y de que ejecutas como Administrador.\")\n        input(\"\\nPresiona Enter para salir...\")\n        sys.exit(1)\n\n    # Configurar el servicio para que se inicie de forma autom\u00e1tica en Windows\n    run_command(f'sc config {SERVICE_NAME} start= auto', \"Configurar servicio en modo autom\u00e1tico\", ignore_error=True)\n\n    # 8. Iniciar el servicio de Windows\n    print(\"\u26a1 [PROCESANDO] Inicializando el servicio en segundo plano de Windows...\")\n    if not run_command(f'\"{sys.executable}\" \"{SENTINEL_SCRIPT}\" start', \"Iniciar Servicio de Windows\"):\n        # Intentar forzar con SC\n        if not run_command(f'sc start {SERVICE_NAME}', \"Iniciar Servicio de Windows con SCM\"):\n            print(\"\ud83d\uded1 [PASO 8 FALLADO] No se pudo iniciar el servicio de Windows reci\u00e9n instalado.\")\n            print(\"\ud83d\udca1 Sugerencia: Revisa los logs de Windows Event Viewer o ejecuta 'python sentinel_printer.py' en consola para ver errores.\")\n            input(\"\\nPresiona Enter para salir...\")\n            sys.exit(1)\n\n    # 9. Verificaci\u00f3n final de salud del servicio HTTP\n    print(\"\ud83c\udfaf [PROCESANDO] Realizando pruebas de conexi\u00f3n finales...\")\n    verify_service_status()\n\n    print(\"\ud83c\udf88 \u00a1ACTUALIZACI\u00d3N v6.0.0 FINALIZADA CON \u00c9XITO! \ud83c\udf88\")\n    print(\"================================================================================\")\n    print(\"  VERSION INSTALADA: v6.0.0\")\n    print(\"  CAMBIOS APLICADOS:\")\n    print(\"  \u2022 Separaci\u00f3n autom\u00e1tica de productos que vengan pegados en un mismo rengl\u00f3n.\")\n    print(\"  \u2022 Impresi\u00f3n limpia de 1 l\u00ednea por producto y suma totalmente coincidente.\")\n    print(\"================================================================ drop-down\\n\")\n    input(\"Presiona Enter para finalizar el instalador... \ud83c\udf1f\")\n\nif __name__ == \"__main__\":\n    main()\n",
};
